import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchBB: [CaseTemplate] = [cornFieldNight, ladderTruck, dogTagScam, chemLawn, pewShove, buffetCarryout, salonWalkout, moversHold, valetGlovebox, rentalTires, poolChemicals, rentalBikeWreck, rampLineFight, raceTicketCopies, souvenirStroller, chargerCable, ticketTearScream, dogBiteSlap, barredSinger, lifeguardChair, benchSmash, utilityGiftCards, payrollCheckCash, mopedWrongWay, beachRoadRace, firePitFeud, treeHouseClimb, bodegaBeer, registerTwenties, groomerCage, drumKitVan, spotFight, bikeLockCutter, photoPrints, swingChains, lockChangeBelongings, plowSmash, trashCanBlaze, aideCash, vapeGrab, foodDriveBox, valveStems, sidewalkLie, resortRobes, gymClose, greenhouseRocks, lunchBenefits, propaneShort]

    static let cornFieldNight = SmallCases.make(
        key: "story.cornFieldNight",
        category: .property,
        headlines: ["Man Fills Truck Bed With Corn From Farmer's Field at Night"],
        law: "misdLarceny",
        spec: "Stole corn valued at $260 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} loaded sweet corn from a field into a truck bed on {DATE}. The headlights were seen at night, and the rows were bare by dawn. The sweet corn was worth $260.",
        state: [E(.video, 3, "Field Camera", "{D} fills bags by headlight."), E(.document, 2, "Harvest Plan", "The field was scheduled to be picked that week.")],
        defense: [E(.statement, 1, "Gleaning", "{DL} says the field was already picked.")],
        role: "Farmer",
        exam: [.direct("What did you find in your sweet corn field on {DATE}?", "\"The rows were bare by dawn. Someone had taken about $260 worth of sweet corn during the night.\""), .direct("What does your field camera show?", "\"It shows {D} filling bags by headlight and loading them into a truck bed. The headlights were seen at night, and the camera caught it.\""), .direct("What was your plan for that field?", "\"It was on our harvest plan to be picked that week. I'd been waiting on the right ripeness.\""), .direct("How big is the field and what was in it?", "\"About four acres of sweet corn planted in late spring, in rows running north to south. It was at peak sweetness that week and ready to pick.\""), .direct("What did you see on the camera?", "\"Around eleven at night a pickup pulled up to the gate and drove in. {DL} walked the rows with a headlamp and filled a dozen burlap bags, carrying them back to the truck.\""), .direct("How did you know how much was taken?", "\"In the morning a whole section of rows was stripped, and the stalks were pulled and broken. I estimated the loss at $260 of retail value.\""), .cross("{DL} says the field was already picked, doesn't {D.he}?", "\"I can't say every row was perfect. But there was corn in that field, and it was mine.\""), .cross("Do you allow gleaning in your fields?", "\"Sometimes, after the harvest is done, and only with permission. {D.He} didn't ask me.\""), .cross("Did you speak to {DL} that night?", "\"No. I was asleep. I saw it on the camera the next morning.\""), .cross("The field was not fenced, was it?", "\"No fence on the road side, only a gate we leave open for equipment. There was a no trespassing sign by the gate.\""), .cross("{D} did not run when your camera light came on, did {D.he}?", "\"No, {D.he} kept right on working. That is part of why I could not tell whether {D.he} knew the field was in use.\"")],
        theory: ("{D} took corn.", "Gleaning."),
        allocution: "\"I work during the day, and night was when I had time to glean what I thought was left in that field. I used my headlights and wasn't hiding. I thought the field had already been picked. I'm sorry to the farmer, and I'll pay for the corn.\"",
        truths: ("The field had not been picked.", "{DL} sold corn at a stand next day."),
        defendant: [.direct("What were you doing in the field?", "\"I thought the field had been picked already. I was gleaning what was left. It's a common practice, and I figured it was fine.\""), .direct("Why did you go at night?", "\"I work during the day. Night is when I had time. I didn't think anyone would mind some leftover corn.\""), .direct("Did you try to hide what you were doing?", "\"No. I used my headlights. I wasn't hiding. I wouldn't have done that if I thought I was stealing.\""), .direct("How did you know about the field?", "\"I had driven past it a few times and saw cut stalks near the road edge. I assumed the crop had been harvested and the rest was left over.\""), .direct("What did you plan to do with the corn?", "\"I took it to a roadside stand I run on weekends and sold it for a few dollars an ear. I did not think it belonged to anyone who still wanted it.\""), .direct("Why did you work with your headlights on?", "\"I had no other light and I did not want to step on something in the dark. I worked in the open and did not hide the truck.\""), .cross("You filled several bags, didn't you?", "\"Yes. I took what I could find. It was more than I expected.\""), .cross("You didn't ask the farmer first, did you?", "\"No. I wish I had. I assumed it was already harvested.\""), .cross("The corn was worth $260, wasn't it?", "\"That's what the farmer says. I didn't think it had that value.\""), .cross("You sold the corn at a stand the next day, didn't you?", "\"Yes, I did. I had thought it was gleaned corn and I sold it for the fuel and my time.\""), .cross("The no trespassing sign was at the gate, wasn't it?", "\"There was a sign. I saw it in the headlights and thought it applied to the road, which was my mistake.\"")],
        openings: ("{V}'s sweet corn field was scheduled to be picked that week, and by dawn the rows were bare. A field camera shows {D} filling bags by headlight at night and loading them into a truck bed.", "The defense will point to a person who believed the field had been picked, gleaned in the open with headlights on, and sold the corn at a small stand. {D} never meant to take a crop that was still wanted."),
        closings: ("Headlights in the field at night, bags filling up, and a $260 crop gone by dawn. A no trespassing sign stood at the gate, and the field had not been picked.", "{D} thought the field was already harvested and worked in the open. The State has not proved {DL} knew the corn still belonged to someone who wanted it."),
        timeline: [(0, "Night: the headlights."), (0, "Dawn: the rows are bare.")],
        identified: "Field Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let ladderTruck = SmallCases.make(
        key: "story.ladderTruck",
        category: .property,
        headlines: ["Worker Takes Extension Ladder From Truck at Job Site"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a contractor, valued at $310, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} took an extension ladder off a contractor's truck on {DATE}. The ladder was on the contractor's truck during the lunch break and was gone by 12:30 p.m. It was worth $310.",
        state: [E(.video, 3, "Site Camera", "{D} lifts the ladder and walks off."), E(.document, 2, "Equipment Label", "The ladder carries the contractor's name.")],
        defense: [E(.statement, 1, "Borrow", "{DL} says {D.he} meant to return it.")],
        role: "Contractor",
        exam: [.direct("What was taken from your truck?", "\"An extension ladder worth about $310. It sat on my truck during the lunch break and was gone by 12:30 p.m.\""), .direct("What does the site camera show?", "\"It shows {D} lifting the ladder off the truck and walking off with it. It is a clear clip, and the walk takes about a minute.\""), .direct("How can you tell the ladder is yours?", "\"It carries my company's name on an equipment label. Every ladder in my truck is marked that way.\""), .direct("What kind of ladder was it?", "\"A twenty-four foot fiberglass extension ladder, orange, with my company name stenciled on both rails. It was strapped to the rack on the truck.\""), .direct("Where was the truck during lunch?", "\"It was parked at the curb in front of the job site while the crew ate at a picnic table in the back. We left the ladder on the rack as we always do.\""), .direct("What did your crew do when you saw the ladder was gone?", "\"I walked the street for a block with two of the crew, then checked the camera and called the sheriff's office. We lost about an hour of work.\""), .cross("Did {D} try to hide the ladder?", "\"No. {D.He} carried it openly across the site in broad daylight. I will give {D.him} that much.\""), .cross("Did anyone tell the defendant it was fine to take it?", "\"Not that I know of. {D.He} says it was borrowed, but no one on my crew told me about any request.\""), .cross("Was the ladder ever returned?", "\"It was recovered later at {D.his} home. I did not get it back until deputies helped.\""), .cross("{D} did not run, did {D.he}?", "\"No, {D.he} walked at a normal pace and even nodded to a passerby. I did not realize it was gone until the crew finished eating.\""), .cross("The ladder was returned, wasn't it?", "\"A deputy recovered it at {DL}'s house two days later. There was a scuff on one rail but nothing serious.\"")],
        theory: ("{D} took a ladder.", "A borrow."),
        allocution: "\"I borrowed that ladder because I needed one at home that afternoon, and I figured I'd bring it right back. I didn't ask, and I should have. I used it for a small job and then returned it. I'm sorry to the contractor, and I'll cover any trouble I caused.\"",
        truths: ("{DL} asked no one.", "The ladder was marked."),
        defendant: [.direct("Did you take the ladder from the truck?", "\"Yes, I borrowed it. I needed a ladder at home that afternoon, and I figured I would return it.\""), .direct("Did you ask anyone before you took it?", "\"No. I did not ask. I should have, and I see now that was my mistake.\""), .direct("Where did you take the ladder?", "\"Home. I took it straight to my house and used it for a small job, then planned to bring it back.\""), .direct("Why did you need a ladder that afternoon?", "\"I had to clear leaves out of my gutters before a storm. My own ladder was too short, and I saw the contractor's ladder as I walked by.\""), .direct("How did you plan to return it?", "\"I figured I would carry it back by evening and lean it against the truck. I did not have a way to contact anyone at the job.\""), .direct("When did you bring it back?", "\"I did not get the chance, because the deputies arrived first. I would have returned it that night.\""), .cross("Your word for it is borrowed, but no one lent it to you, did they?", "\"That is true. No one lent it to me. I took it on my own without asking, and I know how that sounds.\""), .cross("The ladder had the contractor's name on it. Didn't that tell you it was not yours?", "\"Of course I knew it was not mine. I told myself it was only for a few hours.\""), .cross("You took it during the lunch break when no one was watching, didn't you?", "\"I took it when I saw it was unattended. I did not think anyone would mind.\""), .cross("You never asked a person at the site for permission, did you?", "\"No, I did not. It was lunchtime and no one was nearby, so I took what I thought would not be missed.\""), .cross("The company name on the rails told you whose it was, didn't it?", "\"It did, and I understood that it belonged to someone. That is why I called it a borrow rather than a gift.\"")],
        openings: ("During a lunch break, an extension ladder worth $310 vanished from a contractor's truck. A site camera shows {D} lifting it off and walking away, and the ladder carried the contractor's name.", "Jurors will hear that {D} meant only to borrow the ladder for a short job, carried it openly in daylight, and had no plan to sell it. {D.He} did not ask because no one was around."),
        closings: ("The camera shows {D} carrying off a ladder marked with the contractor's name, and no one was asked. Borrowing needs a lender, and nobody lent this one.", "{D} carried the ladder in broad daylight and took it home, not to a pawn shop. That is poor judgment, but the State has not proved a plan to keep it."),
        timeline: [(0, "Noon: lunch break."), (0, "12:30 p.m.: the ladder is gone.")],
        identified: "Site Camera",
        mood: .indifferent)

    static let dogTagScam = SmallCases.make(
        key: "story.dogTagScam",
        category: .whiteCollar,
        headlines: ["Woman Sells Fake Dog License Tags Door to Door"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $40, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} sold fake county dog license tags door to door on {DATE}. The knock came in the morning, and the county said the next day that the tag was not real. {D.He} sold the tags for $40 each.",
        state: [E(.physical, 3, "Tags", "Tags with no county stamp."), E(.document, 2, "County Statement", "The county does not issue that tag.")],
        defense: [E(.statement, 1, "Real", "{DL} says the tags were real.")],
        role: "Homeowner",
        exam: [.direct("What happened at your door on {DATE}?", "\"{D} knocked in the morning and sold me a county dog license tag for $40. I bought it believing it was official.\""), .direct("What did you learn about the tag?", "\"The next day, the county told me it does not issue that tag. The tag had no county stamp on it.\""), .direct("What does the tag look like?", "\"A tag with no county stamp. It looked official enough to me, but it wasn't.\""), .direct("What did {D} say at the door?", "\"{D.He} said the county was requiring new dog licenses and that tags had to be bought that day to avoid a fine. {D.He} had a clipboard and a box of tags.\""), .direct("How did you pay?", "\"I wrote a check for $40 and {D.he} handed me a metal tag stamped with a number. I hung it on my dog's collar that afternoon.\""), .direct("What did you do after you learned the tag wasn't real?", "\"I went to the county office with the tag and the bill of sale, and they took a copy of both.\""), .cross("{DL} says the tags were real, doesn't {D.he}?", "\"The county says they aren't. I only know what the county told me.\""), .cross("Did {DL} say anything false to you?", "\"{D.He} said it was a county license tag. I took that at face value. I didn't check.\""), .cross("Did you check with the county before paying?", "\"No. I know I should have. It was a quick sale, and I wanted to be legal.\""), .cross("{D} gave you a receipt, didn't {D.he}?", "\"A handwritten slip with a date and an amount, but no business name. I did not look closely at the time.\""), .cross("Neighbors also bought tags, didn't they?", "\"Several did, I learned later. I do not know exactly how many, and I only spoke with a few.\"")],
        theory: ("{D} sold fake tags.", "Real tags."),
        allocution: "\"I bought those tags from a supplier, and I believed they were real county tags. I sold them door to door for forty dollars because that's what I was told the fee was. I'm sorry to every household I sold to. I'll refund each of them.\"",
        truths: ("The county never issued them.", "{DL} had a box of 200."),
        defendant: [.direct("Where did you get the tags?", "\"From a supplier. I thought they were real county tags. I sold them door to door, as I was told to.\""), .direct("Did you know they were fake?", "\"No. If I had known, I would not have sold them. I believed they were legitimate.\""), .direct("Why did you charge $40?", "\"That's what I was told the county fee was. I passed it along. I didn't think I was overcharging anyone.\""), .direct("How did you get into selling tags?", "\"A supplier at a trade show offered me a box of two hundred at a low price. I was told they were approved and I could sell them door to door.\""), .direct("What did you tell people at the door?", "\"That the tags were dog licenses and that the fee was $40. I repeated what I had been told by the supplier.\""), .direct("What did you do after learning they were fake?", "\"I stopped selling at once and wrote to the supplier, who never answered. I do not know where the supplier is now.\""), .cross("The county says it doesn't issue that tag, doesn't it?", "\"That's what I hear. I'm shocked. I didn't know.\""), .cross("Your tags had no county stamp, did they?", "\"They looked normal to me. I didn't look for a stamp. I wish I had.\""), .cross("You sold door to door, didn't you?", "\"Yes. It's how I was told to do it. I never thought it was a scam.\""), .cross("You never confirmed the fee with the county, did you?", "\"No. I took the supplier's word, and I should have called.\""), .cross("You sold tags from a box of 200, didn't you?", "\"Yes. I bought the box and sold as many as I could. I did not check whether the county would honor them, and I should have.\"")],
        openings: ("{D} went door to door selling county dog license tags for $40 each. The county says it never issued the tags, and the metal discs carry no county stamp.", "Jurors will also see a seller who bought a box of two hundred tags from a supplier, believed they were genuine, and sold them openly. {D} stopped the moment the problem came out."),
        closings: ("A $40 tag with no county stamp, a county that never issued it, and a seller at the door. Residents paid for a license and got a worthless piece of metal.", "{D} believed the tags were genuine and sold them openly, at the door, to anyone who asked. The State has not proved {DL} knew they were fake."),
        timeline: [(0, "Morning: the knock."), (1, "The county says no.")],
        identified: "Tags",
        mood: .indifferent,
        genders: ["D": .female])

    static let chemLawn = SmallCases.make(
        key: "story.chemLawn",
        category: .publicOrder,
        headlines: ["Man Sprays Weed Killer on Neighbor's Lawn in Feud"],
        law: "disorderly",
        spec: "Willfully injured property of {V}, a neighbor, with chemicals, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} sprayed weed killer across a neighbor's lawn on {DATE}. The spray came in the morning, and the grass died two days later in a straight stripe. The damage cost $400.",
        state: [E(.video, 3, "Porch Camera", "{D} sprays a line."), E(.document, 2, "Lawn Estimate", "$400 to re-sod the dead stripe.")],
        defense: [E(.statement, 1, "Drift", "{DL} says wind blew it.")],
        role: "Neighbor",
        exam: [.direct("What did you notice on your lawn on {DATE}?", "\"Two days after a spray, the grass died in a straight stripe. It was a clean line across my lawn.\""), .direct("What did it cost?", "\"$400 to re-sod the dead stripe. I have the lawn estimate. It looks awful until it's replaced.\""), .direct("What did your lawn look like before?", "\"Thick green fescue that I seeded two years ago and watered every other day. It ran right up to the fence between our yards.\""), .direct("What did you see after the spray?", "\"Two days later a brown stripe about eight inches wide ran along the whole fence line. It was perfectly straight and the grass inside was dead to the roots.\""), .direct("What does your porch camera show?", "\"{D} walks along the fence with a pump sprayer, aiming the nozzle at the ground on my side. It takes about three minutes.\""), .direct("What did you do after you saw the dead stripe on your lawn?", "\"I called a lawn company for an estimate and photographed the line. The straight edge told me it was sprayed, not blown by wind.\""), .cross("{DL} says wind blew it, doesn't {D.he}?", "\"The stripe is straight, which is not how drift looks. But I'm not an expert.\""), .cross("Did you see {DL} spray?", "\"I saw it on the camera. I wasn't outside at the time.\""), .cross("Did you and {DL} argue before?", "\"We've had disagreements about our property lines. Nothing serious. I wouldn't have expected this.\""), .cross("You and {D} have disagreed about the line before, haven't you?", "\"We talked about where the fence should be, but nothing ever got heated. I never thought it would come to this.\""), .cross("The camera does not show wind moving the trees, does it?", "\"The branches are still. It looked calm that morning, which is why I did not expect drift.\"")],
        theory: ("{D} killed a lawn.", "Drift."),
        allocution: "\"I was spraying weeds along my own fence, and the wind carried it over onto my neighbor's lawn. I'd never do that on purpose. I'm sorry for the stripe of dead grass and for the four hundred dollars it cost to fix. I'll sod the lawn myself.\"",
        truths: ("The line is straight.", "The day was calm."),
        defendant: [.direct("What were you spraying?", "\"Weed killer along my own edge. I was treating weeds by the fence. I didn't mean to hit {V}'s lawn.\""), .direct("How did it get on the lawn?", "\"The wind blew it. I sprayed my side, but a gust carried it over. I didn't aim at the lawn.\""), .direct("Did you intend to damage the lawn?", "\"No. I'd never do that to a neighbor.\""), .direct("What were you trying to kill?", "\"The weeds that grow at the base of my fence, about a foot wide. I use the product every spring and aim carefully.\""), .direct("Where were you standing?", "\"On my side of the fence, aiming down at the weeds. I thought I kept the spray low and to the right.\""), .direct("What did you do when you learned about the dead grass?", "\"I told {V} I was sorry and offered to talk. I did not understand how the spray crossed over until I saw the stripe.\""), .cross("The dead stripe is straight, isn't it?", "\"I don't have a good explanation. I just know I wasn't aiming there.\""), .cross("You walked along the line spraying, didn't you?", "\"Yes. That's how I treat weeds. I was careful, but wind is wind.\""), .cross("You've had a dispute with {V}, haven't you?", "\"Some disagreements, yes. That's not why I sprayed. It was about weeds.\""), .cross("You sprayed along the entire fence line, didn't you?", "\"Yes. I covered the full length, and I understand that is how a stripe could form.\""), .cross("A fence blocks the wind a bit, doesn't it?", "\"It does not block it entirely. I recall a light breeze, although I cannot swear to its direction.\"")],
        openings: ("{D} sprayed weed killer along the edge of a neighbor's lawn, and two days later the grass died in a straight brown stripe. The porch camera shows the spraying, and re-sodding costs $400.", "The defense evidence includes a person killing weeds along {D.his} own fence, a breeze that carried the spray, and an apology. {D} never meant to damage a neighbor's lawn."),
        closings: ("A porch camera, a dead stripe, and $400 to fix it. Wind does not draw a straight line along a fence, and a calm morning does not carry spray eight inches over a property line.", "{D} meant to treat weeds on {D.his} own side, and a gust carried it over. The State has not proved a deliberate attack on a neighbor's grass."),
        timeline: [(0, "Morning: the spray."), (2, "The grass dies.")],
        identified: "Porch Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let pewShove = SmallCases.make(
        key: "story.pewShove",
        category: .violent,
        headlines: ["Congregant Shoves Usher Over Seat Dispute"],
        law: "simpleAssault",
        spec: "Assaulted {V} by pushing {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} shoved an usher on {DATE} when asked to move seats. The request came at 10 a.m. and the shove a second later. The pastor saw it from the front of the sanctuary.",
        state: [E(.video, 3, "Sanctuary Camera", "{D} pushes {V}."), E(.statement, 2, "Pastor", "Saw the shove from the front of the sanctuary.")],
        defense: [E(.statement, 1, "Reserved", "{DL} says the seat was {D.his}.")],
        role: "Pastor",
        exam: [.direct("What did you see from the front of the sanctuary?", "\"At about 10 a.m., an usher asked {D} to move seats, and a second later {DL} shoved the usher. I saw it from the front.\""), .direct("How did the usher ask?", "\"Politely. {V} asked {DL} calmly to move to another seat, as ushers do when the sanctuary fills up.\""), .direct("What does the sanctuary camera show?", "\"It shows {DL} pushing {V} backward. It is clear, and the whole thing took only a moment.\""), .direct("How is the service organized?", "\"We hold a morning service at ten with about two hundred people, and the ushers greet people and help them find seats. We try to keep the front rows open for families with small children.\""), .direct("What did you see happen?", "\"An usher came to the pew where {D.he} was sitting and bent down to speak quietly. {D.He} stood up, and I saw a hand go to the usher's chest and push.\""), .direct("What did you do afterward?", "\"I paused the service briefly and walked down to check on the usher. {D.He} left the pew and stood at the back until the end.\""), .cross("Are seats in your sanctuary reserved?", "\"No. Seats are not reserved. Anyone can sit in any pew, and ushers move people only to fit everyone.\""), .cross("Did the usher touch {D} first?", "\"No. I did not see {V} touch {DL} at all before the push.\""), .cross("Was anyone hurt?", "\"No. {V} stumbled but did not fall or get injured. It was a shock more than anything.\""), .cross("You did not hear the words they exchanged, did you?", "\"I could not hear from the pulpit. I could see the usher speaking politely and {D.his} face changing.\""), .cross("{D} has been a member for years, hasn't {D.he}?", "\"Yes, {D.he} has attended for a long time. That makes this a surprise for all of us.\"")],
        theory: ("{D} shoved an usher.", "A reserved seat."),
        allocution: "\"My family has sat in that pew for years, and when I was asked to move, I lost my temper and shoved the usher. I was embarrassed and left without saying a word. I'm sorry to the usher, the pastor, and the congregation. I'll apologize in person.\"",
        truths: ("Seats are not reserved.", "{V} asked politely."),
        defendant: [.direct("Did you shove the usher?", "\"Yes, I did. I lost my temper when I was asked to move from the pew where I had always sat.\""), .direct("Why did the request upset you?", "\"It was my seat. My family has sat in that spot for years, and it felt like I was being pushed out.\""), .direct("Did you apologize afterward?", "\"No, I did not. I was embarrassed, and I left without saying anything. I regret that.\""), .direct("Where do you usually sit?", "\"In the same pew, three rows from the front, on the aisle, with my family. We have sat there for nearly twenty years.\""), .direct("What did the usher say?", "\"That there was a family with young children coming and would I mind moving back a few rows. It was said gently, and I took it badly.\""), .direct("What did you do after the push?", "\"I stood there stunned, then left for the back of the sanctuary. I did not speak to the usher after the service, and I wish I had.\""), .cross("Seats are not reserved, are they?", "\"No. I know that. But it felt like my spot, and I reacted badly.\""), .cross("The usher asked politely, didn't {V.he}?", "\"Yes. {V} was polite. It was my reaction that was wrong.\""), .cross("You shoved someone in a house of worship in front of a congregation, didn't you?", "\"I did. I am ashamed of it. I would take it back if I could.\""), .cross("You pushed with a hand to the chest, didn't you?", "\"I did. It was not a graze, and I knew what I was doing.\""), .cross("Nobody told you the pew was yours, did they?", "\"No. That belief is mine alone, and I know it does not belong to me.\"")],
        openings: ("During a service at 10 a.m., an usher politely asked {D} to move seats. A second later {DL} pushed {V} in the chest, and the pastor saw it from the front of the sanctuary.", "The defense will point to a long-time member who lost a temper over a familiar pew. {D} is ashamed and wants to apologize to the congregation."),
        closings: ("A polite request, a shove, a camera, and a pastor who saw it from the front. Seats are not reserved, and no seat is worth a push.", "One shove in a moment of anger from a congregant who regrets it. No one was hurt, and this was out of character for a member of twenty years."),
        timeline: [(0, "10 a.m.: the request."), (0, "10:01 a.m.: the shove.")],
        identified: "Sanctuary Camera",
        mood: .indifferent)

    static let buffetCarryout = SmallCases.make(
        key: "story.buffetCarryout",
        category: .property,
        headlines: ["Customers Carry Food Out of Buffet in Bags"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a restaurant, valued at $120, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} carried food out of a buffet in bags on {DATE}. The buffet was busy at noon, and the camera shows {DL} filling a bag at about 1 p.m. The food was worth $120.",
        state: [E(.video, 3, "Dining Camera", "{D} fills a bag."), E(.document, 2, "Posted Sign", "A sign forbidding carry-out from the buffet.")],
        defense: [E(.statement, 1, "Leftovers", "{DL} says it was leftovers.")],
        role: "Manager",
        exam: [.direct("What did you see at the buffet on {DATE}?", "\"It was busy at noon. At about 1 p.m., the camera shows {D} filling a bag with food from the buffet.\""), .direct("What's your policy on carry-out?", "\"There's a sign forbidding carry-out from the buffet. It's posted where customers see it.\""), .direct("What was the value of the food?", "\"About $120. {D.He} took a large amount of food in bags.\""), .direct("What was the buffet like that day?", "\"It was the lunch rush with about a hundred diners. We serve hot dishes, a salad bar, and desserts for a flat price of $14 per person.\""), .direct("What did the camera show about {D}'s bag?", "\"{DL} comes in carrying an empty tote and sits for about forty minutes. Later {DL} walks the buffet and scoops chicken, rice, and desserts into containers inside the bag.\""), .direct("How was the food counted?", "\"We estimated about $120 of food from the portions that were gone from the pans. A cook compared our pan weights and counted the trays.\""), .cross("{DL} says it was leftovers, doesn't {D.he}?", "\"Leftovers from a plate are one thing. A bag filled from the buffet line is another.\""), .cross("Did you stop {DL}?", "\"No. I saw it on the camera later. {D.He} walked out before I noticed.\""), .cross("Did {DL} pay for a meal?", "\"I don't know. I'd have to check the register. {D.He} may have paid for a buffet meal.\""), .cross("The sign about carry-out is small, isn't it?", "\"It is about the size of a sheet of paper, mounted at eye level near the register. Many guests walk right past it.\""), .cross("You never spoke to the defendant before the bag was full, did you?", "\"No, my staff did not see it live. We found it on the camera later, and I was not on the floor.\"")],
        theory: ("{D} took buffet food.", "Leftovers."),
        allocution: "\"I paid for my meal, and I took what I'd already served along with a little extra, thinking it was allowed. I'm not that kind of person. I'm sorry to the buffet and the staff. I'll pay for the extra food and I'll ask before I carry anything out.\"",
        truths: ("Signs forbid carry-out.", "The bag was empty on entry."),
        defendant: [.direct("What did you put in the bag?", "\"Food I'd already taken from my plate and some extra. I thought it was leftovers I could take home.\""), .direct("Did you see the carry-out sign?", "\"I didn't notice it. If I had, I wouldn't have taken the bag. I'm not that kind of person.\""), .direct("Did you pay for the buffet?", "\"I paid for my meal. I thought I was allowed to take what I'd already served myself.\""), .direct("Why did you bring a bag in?", "\"I brought a tote for my work things and a few empty containers for my lunch tomorrow. I did not think about whether that would be allowed.\""), .direct("What did you put in the containers?", "\"Some chicken and rice from my plate and a few dessert bars. I filled them while chatting with my companion, and I did not count.\""), .direct("Did anyone say anything to you on the way out?", "\"No. A server smiled as I left and I walked to my car. If someone had said something I would have put it back.\""), .cross("The camera shows you filling a bag, doesn't it?", "\"Yes. I was moving food. I didn't think of it as a big deal.\""), .cross("$120 of food is a lot of leftovers, isn't it?", "\"I took more than I should have, yes. I realize that.\""), .cross("The sign forbade carry-out, didn't it?", "\"I've been told that. I didn't see it. I should have looked.\""), .cross("You walked the buffet line with a bag, didn't you?", "\"Yes, with the bag over my shoulder. I did not see why it mattered.\""), .cross("You never asked whether you could take food home, did you?", "\"No. Many places let you take leftovers, and I assumed it was normal.\"")],
        openings: ("At a busy buffet, the dining camera shows {D} filling a bag with about $120 of food, despite a posted sign forbidding carry-out. {D.He} walked out with it after the lunch rush.", "The defense will present a customer who paid for a meal, believed {D.he} was taking leftovers, and never noticed the sign. {D} was open about the bag from the moment {D.he} walked in."),
        closings: ("A posted sign, a bag filled at noon, and $120 of food walking out the door. A guest who walks the line with an empty tote knows what the tote is for.", "{D} paid for the meal, took leftovers, and never saw a sign. The State has not proved {DL} knew carry-out was forbidden."),
        timeline: [(0, "Noon: the buffet."), (0, "1 p.m.: the bag.")],
        identified: "Dining Camera",
        mood: .indifferent)

    static let salonWalkout = SmallCases.make(
        key: "story.salonWalkout",
        category: .property,
        headlines: ["Customer Walks Out of Salon Without Paying $180"],
        law: "misdLarceny",
        spec: "Stole services valued at $180 from {V}, a salon, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} left a salon on {DATE} without paying for a color treatment. The color started at 2 p.m., and {D.he} walked out at 3:30 p.m. The treatment cost $180.",
        state: [E(.video, 3, "Salon Camera", "{D} walks out."), E(.document, 2, "Service Ticket", "A $180 ticket for the color treatment.")],
        defense: [E(.statement, 1, "Card", "{DL} says the card declined.")],
        role: "Stylist",
        exam: [.direct("What service did {D} receive?", "\"A color treatment. It started at 2 p.m., and the service ticket was for $180.\""), .direct("What happened at 3:30 p.m.?", "\"{D} walked out of the salon without paying. The salon camera shows {DL} leaving through the front door.\""), .direct("What did you do when you realized?", "\"I called out and tried to reach {DL}. {DL} did not come back, and we never saw {DL} again.\""), .direct("How does your salon handle payment?", "\"We take payment at the front desk after the service. A color treatment like this one takes about ninety minutes and is rung up at the end.\""), .direct("What happened when the defendant went to pay?", "\"{D.He} handed over a card and the machine said declined. I asked if there was another card, and {D.he} said it was fine and went to the restroom.\""), .direct("What did you see next?", "\"About five minutes later I noticed {DL}'s coat and bag were gone. The salon camera shows {DL} walking out the front door and down the sidewalk.\""), .cross("{D} says the card was declined, doesn't {D.he}?", "\"Yes, that is what {D.he} said. The card was run, and it did not go through.\""), .cross("Did you offer the defendant a chance to try another card?", "\"I did offer. I told {D.him} to try another card, and {D.he} did not try one.\""), .cross("Did the defendant ever come back to pay?", "\"No. {D.He} never returned. That is why I am here.\""), .cross("The card was declined, wasn't it?", "\"Yes, I saw the screen. It said declined, and {D.he} looked embarrassed.\""), .cross("{D} said something before leaving, didn't {D.he}?", "\"{D.He} told me it must be an error with the bank. I said we could wait, and {D.he} stepped away.\"")],
        theory: ("{D} skipped the bill.", "A declined card."),
        allocution: "\"My card was declined at the chair, and I was too embarrassed to say so. I walked out meaning to come back and pay, and then I let it go for too long. I'm sorry to the stylist. I'll pay the hundred eighty dollars and a tip for the trouble.\"",
        truths: ("{DL} never returned.", "The stylist offered another card."),
        defendant: [.direct("Why did you leave without paying?", "\"My card was declined, and I was embarrassed. I walked out meaning to come back with another way to pay.\""), .direct("Did the stylist offer you another card option?", "\"Yes. The stylist offered, but I did not try another card. I just wanted to leave.\""), .direct("Why did you never return?", "\"I forgot, and then I was too embarrassed. I let it go for too long.\""), .direct("What was going on with the card?", "\"I had a recent charge from a repair that pushed me near my limit. I did not know it would decline for $180.\""), .direct("Why did you not try another card?", "\"I did not have another card on me. I had cash at home, not in my wallet.\""), .direct("What did you plan to do?", "\"I planned to go home, get cash, and come back that evening. When I got home I felt too embarrassed to return.\""), .cross("You walked out in the middle of an exchange about payment, didn't you?", "\"I did. I should have stayed and worked it out. I made a poor choice.\""), .cross("$180 is not a small amount. Why not pay later in person?", "\"I meant to. Weeks went by and I felt worse each day.\""), .cross("You never called the salon, did you?", "\"No. I never called. I was afraid to.\""), .cross("You never went back to the salon, did you?", "\"No. A few weeks went by, and the longer I waited the worse it felt.\""), .cross("You left while the stylist was waiting for payment, didn't you?", "\"Yes. I should have said clearly that I would be right back.\"")],
        openings: ("{D} sat for a color treatment that began at 2 p.m. and cost $180, and at 3:30 walked out of the salon without paying. {D.his} card was declined at the front desk, and {D.he} never returned.", "Listen for the defense evidence, which will show that {D}'s card was declined, that {D.he} was embarrassed, and that {D.he} meant to come back with cash. {D.He} offers to pay every dollar."),
        closings: ("A $180 ticket, a walk through the front door, and no return. Even after the stylist offered another card, {D} slipped out and stayed away.", "A declined card and an embarrassed customer who meant to come back and did not. The State must prove {D} planned to skip the bill from the start."),
        timeline: [(0, "2 p.m.: the color."), (0, "3:30 p.m.: the walkout.")],
        identified: "Salon Camera",
        mood: .indifferent)

    static let moversHold = SmallCases.make(
        key: "story.moversHold",
        category: .whiteCollar,
        headlines: ["Movers Hold Belongings Until Customer Pays Double"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $600, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} held a customer's boxes on a truck on {DATE} until $600 more was paid. The move began in the morning, and the boxes were held on the truck that evening. The final bill was $1,500 against a $900 estimate.",
        state: [E(.document, 3, "Estimate", "The signed estimate for $900."), E(.document, 2, "Final Bill", "A $1,500 bill against a $900 estimate.")],
        defense: [E(.statement, 1, "Extra", "{DL} says the load was larger.")],
        role: "Customer",
        exam: [.direct("What was the signed estimate?", "\"$900. The movers signed an estimate for $900, and I agreed to that amount before the move began in the morning.\""), .direct("What happened on the evening of the move?", "\"The movers held my boxes on the truck until I paid $600 more. The final bill was $1,500.\""), .direct("Did the load change from the estimate?", "\"No. The load matched what we agreed to. Nothing was added, and no one weighed it again.\""), .direct("What did you hire the movers to do?", "\"Move a two-bedroom apartment across town, about eleven miles. The estimate covered two movers, a truck, and a standard load of furniture and boxes.\""), .direct("How did the day go?", "\"They loaded in the morning and arrived at the new place around four in the afternoon. At the curb the lead mover said the bill was now $1,500.\""), .direct("What did the mover say about the boxes?", "\"The mover refused to unload until I paid the extra $600. I had a house to set up, so I paid it by card on the curb.\""), .cross("{D} says the load was bigger than estimated, doesn't {D.he}?", "\"That is what {D} said. But I had the same items I listed on the estimate.\""), .cross("Did you pay the extra amount?", "\"I paid because my belongings were on the truck. I felt I had no choice.\""), .cross("Did the defendant threaten to damage anything?", "\"No. {D.He} just said the boxes would not come off until I paid.\""), .cross("You counted the boxes before the move, correct?", "\"Yes, I had forty-two boxes and the furniture listed on the estimate. Nothing was added that I know of.\""), .cross("Did anyone give you a receipt for the extra payment?", "\"No. They took cash and said I'd get a receipt later, and I never did.\"")],
        theory: ("{D} held the load.", "A bigger load."),
        allocution: "\"The load turned out bigger than I expected, and I eyeballed it and went by my judgment instead of reweighing. I held those boxes until I'd be paid for the extra work, which is how I thought it worked. I'm sorry to the customer. I'll return the six hundred dollars.\"",
        truths: ("The load matched the estimate.", "{DL} never reweighed."),
        defendant: [.direct("Why did you charge the customer more than the estimate?", "\"The load was bigger than I expected. I thought we had more boxes and furniture than on the estimate.\""), .direct("Did you weigh the load again?", "\"No. I did not reweigh it. I eyeballed it and went by my judgment.\""), .direct("Why did you hold the boxes?", "\"I wanted to be paid for the extra work before I unloaded. That is how I operate.\""), .direct("What did you see when you arrived at the apartment?", "\"More furniture than the estimate described, including a heavy sectional and a large dresser. It looked like a bigger job than I planned for.\""), .direct("How did you arrive at $1,500?", "\"I figured extra time for the two extra pieces and the stairs. I added it up in my head and told the customer at the curb.\""), .direct("Why did you keep the boxes on the truck?", "\"I wanted to be paid before unloading because I had been burned before. It was not meant to scare anyone.\""), .cross("The signed estimate was $900. Why charge $1,500?", "\"I thought the load was bigger. I should have documented it better.\""), .cross("You held a person's belongings until they paid an extra $600, didn't you?", "\"I see now how that looks. I did not mean to hold anyone hostage.\""), .cross("You never reweighed, so how do you know it was bigger?", "\"I did not. I made a call by eye, and I may have been wrong.\""), .cross("The estimate did not list the sectional as extra, did it?", "\"I do not think it did. I assumed the customer would understand a bigger load costs more.\""), .cross("You never weighed anything after loading, did you?", "\"No. I judged it by eye, and I know that is not how a bill should be built.\"")],
        openings: ("{V} signed a $900 estimate for a move. That evening {D} held {V}'s boxes on the truck until {V.he} paid $600 more, bringing the final bill to $1,500.", "The defense case is that {D} honestly believed the load was bigger than estimated and wanted to be paid for the extra work. {D.He} did not threaten damage and unloaded once payment was made."),
        closings: ("A $900 estimate, a $1,500 bill, and boxes held on a truck until the customer paid. The load matched what was agreed, and nothing weighed more.", "A mover who believed the load was larger and who did not weigh it again. A billing dispute is a matter for a civil court, not a crime."),
        timeline: [(0, "Morning: the move."), (0, "Evening: the hold.")],
        identified: "Estimate",
        mood: .indifferent)

    static let valetGlovebox = SmallCases.make(
        key: "story.valetGlovebox",
        category: .property,
        headlines: ["Valet Takes Cash From Customer's Glove Box"],
        law: "misdLarceny",
        spec: "Stole property of {V}, valued at $200, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} took $200 from a car glove box while parking it on {DATE}. The valet took the car at 7 p.m., and the glove box was opened three minutes later. {V} had left $200 in it.",
        state: [E(.video, 3, "Garage Camera", "{D} opens the glove box."), E(.statement, 2, "{V}", "Left $200 in the glove box.")],
        defense: [E(.statement, 1, "Looking", "{DL} says {D.he} was looking for a registration.")],
        role: "Customer",
        exam: [.direct("What did you leave in your glove box?", "\"$200 in cash. I left it there when I gave the car to the valet at 7 p.m.\""), .direct("What does the garage camera show?", "\"It shows {D} opening my glove box about three minutes after taking the car. The camera clearly shows it.\""), .direct("What did you find afterward?", "\"The $200 was gone. I checked the glove box when I got the car back, and the cash was missing.\""), .direct("Why did you leave cash in the glove box?", "\"I was heading to dinner and did not want to carry a lot of cash in my pocket. The $200 was in a plain envelope, tucked behind the owner's manual.\""), .direct("How did the valet process go?", "\"I handed the keys to {D.him} at the curb at about seven, got a ticket, and walked inside. {D.He} drove the car down into the garage.\""), .direct("What did you do when you came back?", "\"At nine I got the car back, drove a few blocks, and reached for the envelope to pay for parking elsewhere. It was empty, and I turned around.\""), .cross("{D} says the registration was in the glove box, doesn't {D.he}?", "\"I think the registration was on the dash. I would not have kept it in the glove box.\""), .cross("Did you see the defendant take the cash?", "\"No. I saw only the camera footage later. It shows the glove box open, not the cash.\""), .cross("Did the defendant work as a valet regularly?", "\"Yes. {D.He} was working that night, and I had no earlier problem with the garage.\""), .cross("How long was the garage footage?", "\"About forty minutes. I reviewed all of it with the owner, and the time stamp matches the hour {D} was in the garage.\""), .cross("Other valets also handled the car, didn't they?", "\"I believe a second valet moved the car to a different level later. I do not know who else touched the glove box.\"")],
        theory: ("{D} took cash.", "A search for paper."),
        allocution: "\"I was looking in that glove box for the registration, which our garage requires on the dash. I never saw any cash, and I closed it right away. I'm sorry for the worry to {V}. I stand by my account and I'll cooperate with anyone who wants to check my work.\"",
        truths: ("{DL} pocketed cash.", "The registration was on the dash."),
        defendant: [.direct("Did you open the glove box?", "\"Yes, I did. I was looking for the registration. Valets often check the glove box for it.\""), .direct("Did you take any cash from it?", "\"No. I did not take anything. I did not see any cash, and I closed it right away.\""), .direct("Why look in the glove box at all?", "\"For the registration. Our garage requires it on the dash, and I could not find it, so I looked in the glove box.\""), .direct("What is the process for logging a car in?", "\"We write the plate and the model on a ticket and check for a registration, because the garage insurance requires it. That is why I look in the glove box sometimes.\""), .direct("What did you find when you opened it?", "\"A manual, napkins, and a tire gauge. I did not see any envelope or cash, and I closed it right away.\""), .direct("Where was the registration?", "\"I never found it in the glove box. I assumed the owner had it on the dash, and I wrote the plate on the ticket instead.\""), .cross("The registration was on the dash, wasn't it?", "\"I did not see it there. Maybe it was, but I did not notice.\""), .cross("You opened a customer's glove box three minutes after parking, didn't you?", "\"I did. It is part of the job when the registration is not on the dash.\""), .cross("The $200 was gone after you were alone with the car. Who else could have taken it?", "\"I do not know. I did not take it. Others had access to the car later.\""), .cross("You were alone with the car when you parked it, weren't you?", "\"Yes, I parked it alone on the second level. I did not see anyone else near the car while I was there.\""), .cross("The envelope was gone when the owner returned, wasn't it?", "\"That is what the owner said. I did not see it, and I did not take it.\"")],
        openings: ("{V} left $200 in a glove box when the valet took the car at 7 p.m. Three minutes later, a garage camera shows {D} open the glove box, and the cash was gone when {V} got the car back.", "Weigh the defense proof, which will show that {D} opened the glove box only to look for registration paper, as the garage requires. No one saw {DL} take anything, and no cash was ever found on {DL}."),
        closings: ("A glove box opened three minutes after the keys were handed over, and $200 missing afterward. The camera puts {D}'s hand in the box with no one else near.", "A valet looked for a registration and found no cash. The State has a camera, but it has no footage of money leaving the car, and at least one other valet handled it."),
        timeline: [(0, "7 p.m.: valet."), (0, "7:03 p.m.: the glove box.")],
        identified: "Garage Camera",
        mood: .indifferent)

    static let rentalTires = SmallCases.make(
        key: "story.rentalTires",
        category: .whiteCollar,
        headlines: ["Customer Returns Rental Car With Swapped Tires"],
        law: "falsePretenses",
        spec: "Obtained property of {V}, a rental company, by deception, $700, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} swapped good tires on a rental for bald ones on {DATE}. The rental went out with good tires and came back three days later with bald ones. The tires had different serial numbers.",
        state: [E(.physical, 3, "Tires", "Bald tires with different serials."), E(.document, 2, "Pickup Inspection", "The tires were checked and signed off at pickup.")],
        defense: [E(.statement, 1, "Wear", "{DL} says the tires wore down.")],
        role: "Rental agent",
        exam: [.direct("What was the condition of the tires when the rental went out?", "\"Good. We checked and signed off the tires at pickup. The inspection form shows them in good condition.\""), .direct("What did you find when it came back?", "\"The rental came back three days later with bald tires. The serial numbers on the tires were different from the ones we recorded.\""), .direct("How far had the rental been driven?", "\"About 200 miles. That is not enough to wear down good tires to bald.\""), .direct("What do you do at pickup?", "\"We walk around the car with the renter and note the condition of the body and tires. We write down the tire brand, tread depth, and the serial numbers stamped on the sidewalls.\""), .direct("What were the tires like when the car went out?", "\"Four matching all-season tires with plenty of tread, about eight thirty-seconds of an inch. The renter signed the form that day.\""), .direct("What did you notice at return?", "\"The tread was nearly gone, down to about two thirty-seconds, and the sidewall numbers did not match the form. They were an older brand altogether.\""), .cross("Could the tires have worn out from the miles driven?", "\"Not in 200 miles. That would not do it, and the serials do not match either.\""), .cross("Did anyone see {D} swap the tires?", "\"No. No one saw {D} swap anything. We have the tires and the paperwork.\""), .cross("Were there other renters between pickups?", "\"No. It was out on this rental the whole time, so this renter had it.\""), .cross("The renter signed off on pickup without checking serials, didn't {D.he}?", "\"That is common, honestly. Most renters sign what we hand them and do not read the serial column.\""), .cross("You do not know where the defendant drove, do you?", "\"The odometer showed about 200 miles. I do not have a log of the route.\"")],
        theory: ("{D} swapped tires.", "Normal wear."),
        allocution: "\"I never touched those tires. I drove the rental about two hundred miles on a few short trips and one longer drive, and I brought it back. They looked fine at pickup, though I didn't check closely. I'm sorry for the confusion with the rental company.\"",
        truths: ("The serials differ.", "The rental was 200 miles."),
        defendant: [.direct("Did you swap the tires on the rental?", "\"No. I did not touch the tires. I drove the rental and brought it back.\""), .direct("Were the tires worn when you picked it up?", "\"They looked fine at pickup, I thought. But I did not check closely, and I signed what they gave me.\""), .direct("How far did you drive?", "\"About 200 miles. I did a few short trips and one longer drive.\""), .direct("What did you use the car for?", "\"A short trip to see family, then errands around town. I drove mostly on highways at normal speeds.\""), .direct("What did you notice about the tires?", "\"Nothing out of the ordinary during the trip. They felt fine, and the car handled well.\""), .direct("What did you do at return?", "\"I parked in the return lane, handed the key to the agent, and signed the closeout sheet. The agent mentioned the tires a day later.\""), .cross("The tires you returned had different serial numbers. How does that happen?", "\"I do not know. I did not change them. Someone else may have.\""), .cross("You signed the pickup inspection, didn't you?", "\"Yes. I signed what they handed me, and I did not look at the serials.\""), .cross("Bald tires from a 200-mile drive. Does that seem right?", "\"No. It does not. But I did not do it.\""), .cross("The car was in your care for three days, wasn't it?", "\"Yes, three days. It was parked in a lot for much of that time, and I did not leave it with anyone.\""), .cross("You never took pictures of the tires at pickup, did you?", "\"No. I trusted the inspection sheet and did not think I would need proof.\"")],
        openings: ("A rental car went out with good tires, checked and signed off at pickup, and came back three days later with bald tires carrying different serial numbers. The car had been driven only 200 miles.", "Jurors will hear that {D} never touched the tires and that no one saw any swap. The paperwork was signed at pickup without anyone checking the serial numbers."),
        closings: ("Good tires out, bald tires back, different serial numbers, and only 200 miles driven. Tires do not change brands or wear to the cords in a short drive.", "No one saw a swap, and the paperwork was signed at pickup without checking serials. The State has not proved who changed the tires or when."),
        timeline: [(0, "Pickup."), (3, "Return.")],
        identified: "Tires",
        mood: .indifferent)

    static let poolChemicals = SmallCases.make(
        key: "story.poolChemicals",
        category: .property,
        headlines: ["Man Takes Pool Chemicals From Store Lot"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a store, valued at $290, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} loaded pool chemicals from a store lot on {DATE}. {D.He} loaded the buckets at about noon and left twenty minutes later. The buckets carried the store's tags.",
        state: [E(.video, 3, "Lot Camera", "{D} loads buckets."), E(.document, 2, "Receipt", "{D}'s receipt for fewer buckets than were loaded.")],
        defense: [E(.statement, 1, "Mistaken", "{DL} says they were {D.his}.")],
        role: "Store manager",
        exam: [.direct("What does the lot camera show?", "\"It shows {D} loading buckets of pool chemicals into a vehicle at about noon and leaving about twenty minutes later.\""), .direct("How can you tell they were ours?", "\"The buckets carried the store's tags. Each one is priced and tagged before it goes on the shelf.\""), .direct("What about {D}'s receipt?", "\"{D.He} had a receipt for fewer buckets than were loaded. The difference is what concerns us.\""), .direct("What do you sell in the outdoor area?", "\"Pool chemicals in sealed five-gallon buckets, stacked on pallets near the entrance. Each bucket has a store tag and a barcode on the lid.\""), .direct("What did you see on the camera?", "\"{D.He} drives up to the pallet, loads buckets into a truck bed one after another, and then goes inside to the register. The load takes about twenty minutes.\""), .direct("How many buckets were unpaid?", "\"The receipt covers four buckets, and the camera shows {DL} loading eight. That is four unpaid at about $30 each, plus tax, for $120 or more.\""), .cross("Could the defendant have thought all the buckets were covered by the receipt?", "\"It is possible. I do not know what {D.he} thought, and counting is easy to get wrong.\""), .cross("Did the defendant try to hide the buckets?", "\"No. {DL} loaded them in the open, in the lot, in view of the camera.\""), .cross("{D} loaded in the open in daylight, correct?", "\"Yes, at noon in a busy lot. There were customers and staff around, and {D.he} made no effort to cover the load.\""), .cross("The buckets look much like others sold by other stores, don't they?", "\"They look similar, but ours carry the store tag. A person loading quickly might not read the tag.\""), .cross("{D} went inside to the register after loading, didn't {D.he}?", "\"Yes, the camera shows {D.him} going inside and coming back out with a receipt, which covers only four buckets.\"")],
        theory: ("{D} took chemicals.", "His own."),
        allocution: "\"I thought I'd paid for all of those buckets. I trusted the checkout and loaded them as they were handed to me, and I didn't count. I'm sorry if it was a mix-up on my part. I'll pay the store for any difference.\"",
        truths: ("The buckets had store tags.", "{DL} had a receipt for fewer."),
        defendant: [.direct("Did you take buckets you did not pay for?", "\"I thought they were mine. I believed I had paid for all of them.\""), .direct("What did your receipt cover?", "\"Fewer buckets than I loaded. I did not notice the difference until later.\""), .direct("Did you count the buckets?", "\"No. I did not count them. I trusted the checkout and loaded them as they came.\""), .direct("What did you buy that day?", "\"Chemicals for my pool and for a neighbor's, because they had asked me to pick up a few. I paid for four and expected the rest to be on the same receipt.\""), .direct("How did you load the truck?", "\"I loaded the buckets I thought were on my list, then I went to pay. The cashier handed me a receipt, and I did not count it.\""), .direct("What did you do when you learned the count was off?", "\"I felt sick, because I do not take things. I called the store the next day to say I would sort it out, and then I put it off.\""), .cross("The buckets had store tags, didn't they?", "\"They did. I did not look closely at the tags. I just grabbed and loaded.\""), .cross("You loaded for twenty minutes and never counted?", "\"I should have. I was in a rush, and I did not think about it.\""), .cross("Did you go back to the store when you learned?", "\"No. I did not. I know I should have, and I apologize.\""), .cross("You never went back to correct the receipt, did you?", "\"No, I did not. I told myself I would do it after work and never did.\""), .cross("You loaded eight and paid for four, correct?", "\"That is what the camera and the receipt show. I understand the numbers and I cannot argue with them.\"")],
        openings: ("A lot camera shows {D} loading eight buckets of pool chemicals at noon, and {D.his} receipt covers only four. Each bucket carried the store's tag, and the unpaid buckets were worth $120.", "The defense evidence will establish that {D} loaded in the open, believed every bucket was paid for, and meant to settle any mistake. {D.He} did not hide the truck or the load."),
        closings: ("More buckets loaded than paid for, each tagged by the store, and a receipt that shows the difference. A customer who counts the load at the register would have caught it.", "A customer who loaded openly and did not count. The State must prove {D} knew the receipt was short when leaving, and the open loading points to an honest error."),
        timeline: [(0, "Noon: the lot."), (0, "12:20 p.m.: the load.")],
        identified: "Lot Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let rentalBikeWreck = SmallCases.make(
        key: "story.rentalBikeWreck",
        category: .property,
        headlines: ["Customer Wrecks Rental Bike and Walks Away"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a bike rental, causing damage of $650, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} crashed a rental bike on {DATE} and left it in a ditch. The bike was rented at 2 p.m., and it was found in the ditch an hour later. The frame was bent.",
        state: [E(.video, 3, "Trail Camera", "{D} throws the bike down."), E(.document, 2, "Repair Estimate", "$650 to replace the bent frame.")],
        defense: [E(.statement, 1, "Fall", "{DL} says {D.he} fell.")],
        role: "Rental clerk",
        exam: [.direct("What happened to the rental bike?", "\"It was rented at 2 p.m. and found in a ditch an hour later with a bent frame.\""), .direct("What does the trail camera show?", "\"It shows {D} throwing the bike down. It does not look like a fall. The bike is thrown, and {D.he} walks off.\""), .direct("What did the repair cost?", "\"$650 to replace the bent frame. The estimate is in our file.\""), .direct("How does your bike rental work?", "\"Renters leave an ID and a card, sign a waiver, and take a hybrid bike with a helmet. Rentals run by the hour, and bikes are numbered and tracked.\""), .direct("Who rented the bike?", "\"A customer with a card in the defendant's name. The rental agreement shows the signature and the time.\""), .direct("Whose bike was it?", "\"Number twelve, rented to {D.him} at two. {D.He} was nowhere in sight and never called the shop.\""), .cross("Couldn't the bike have fallen when {D} crashed?", "\"The camera shows {DL} throwing it, not crashing. That is why I say it was thrown.\""), .cross("Did the defendant tell the shop about the damage?", "\"No. {D.He} left without telling us. We found the bike ourselves in the ditch.\""), .cross("Was the defendant hurt?", "\"I do not know. I did not see any injury on the video.\""), .cross("A fall can bend a frame, can't it?", "\"It can. This frame was bent sharply at the head tube, and I cannot say whether a fall or a throw did it.\""), .cross("{D} gave you a card and an ID, didn't {D.he}?", "\"Yes, and that is how we contacted {DL} afterward. {DL} returned the call a few days later.\"")],
        theory: ("{D} wrecked a bike.", "A fall."),
        allocution: "\"I took a fall on that rental bike and it went into the ditch, and I was shaken and angry, so I walked away. I should have gone straight to the shop and told them. I'm sorry for the bent frame.\"",
        truths: ("The bike was thrown.", "{DL} left without telling."),
        defendant: [.direct("Did you wreck the bike on purpose?", "\"No. I had a fall. The bike went into the ditch, and I was upset.\""), .direct("Did you leave the bike in the ditch?", "\"Yes. I left it. I was shaken and angry, and I walked away.\""), .direct("Did you tell the shop?", "\"No. I did not tell the shop. I should have, and I did not know what to say.\""), .direct("What happened on the trail?", "\"I was riding downhill and hit a root, and the front wheel twisted and I went over the handlebars. I slid on gravel and scraped my arm.\""), .direct("How did you feel afterward?", "\"Embarrassed. I went home, and the next morning I called the shop to say where the bike was.\""), .direct("Why did you not go back to the shop?", "\"I was embarrassed and sore, and I thought they would charge me a lot. I took a long walk and then went home.\""), .cross("A bent frame costs $650. Will you pay?", "\"I would be willing to. I did not mean to cause that much damage.\""), .cross("You left without telling anyone, didn't you?", "\"I did. I panicked, and I apologize.\""), .cross("The camera shows you throwing the bike, doesn't it?", "\"Yes. It shows me lifting it and flinging it down the bank, which is a different thing from a crash.\""), .cross("You did not call the shop until they called you, did you?", "\"That is right. I was too embarrassed, and I regret it.\""), .cross("You did not offer to pay for the frame until the shop called you, did you?", "\"That is true. I was embarrassed and avoided the call at first. I would have paid the $650 if I had faced it sooner.\"")],
        openings: ("A rental bike was rented at 2 p.m. and found an hour later in a ditch off the trail with a bent frame. A trail camera shows {D} throwing the bike down before walking away.", "By the end of this trial, the proof will show that {D} fell on the trail, lost a temper in the moment, and walked away out of embarrassment. {D.He} offers to pay for the damage."),
        closings: ("A bike thrown down on camera, a bent frame, $650 in repairs, and a renter who walked away without a word. A fall explains a scrape but not a bike flung into a ditch.", "A fall, a frayed temper, and an embarrassed rider who left. {D} will pay for the damage, and a rented bike is not a reason to punish someone beyond that."),
        timeline: [(0, "2 p.m.: the rental."), (0, "3 p.m.: the ditch.")],
        identified: "Trail Camera",
        mood: .indifferent)

    static let rampLineFight = SmallCases.make(
        key: "story.rampLineFight",
        category: .violent,
        headlines: ["Anglers Fight at Boat Ramp Over Launch Line"],
        law: "simpleAssault",
        spec: "Assaulted {V} by striking {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} punched another angler on {DATE} over the launch line. The launch line formed at 5 a.m., and the punch came twenty minutes later. {V} was left with a split lip.",
        state: [E(.video, 3, "Ramp Camera", "{D} punches {V}."), E(.document, 2, "Medical Note", "A cut lip.")],
        defense: [E(.statement, 1, "Cut", "{DL} says {V} cut the line.")],
        role: "Ramp attendant",
        exam: [.direct("What happened at the boat ramp?", "\"The launch line formed at 5 a.m. About twenty minutes later, {D} punched {V}, another angler, in the face.\""), .direct("What does the ramp camera show?", "\"It shows {DL} punching {V}. It is a single blow, and then people step in between.\""), .direct("What was {V}'s injury?", "\"A cut lip. A medical note records it, and {V} needed to clean it up before launching.\""), .direct("How does the launch line work?", "\"Anglers line up their trucks and trailers in the order they arrive, starting before dawn. Each boat launches in turn and the line moves up the ramp.\""), .direct("What did you see between {D} and {V}?", "\"Around 5:20 {DL} walked up to {V}'s truck and the two argued loudly about the order. {V} raised a hand, and {DL} swung and hit {V} in the mouth.\""), .direct("What did you do?", "\"I stepped between them and told everyone to back away. {V} was bleeding from the lip, and I handed over a clean towel.\""), .cross("Did {V} wait in line?", "\"Yes. {V} waited in line like everyone else. I did not see any cutting.\""), .cross("{D} says {V} cut in line, doesn't {D.he}?", "\"That is what {DL} says. I did not see a cut. The line was long.\""), .cross("Did {V} raise a hand first?", "\"I think {V} raised a hand. I cannot say whether it was to point or to strike.\""), .cross("The line was a busy one that morning, wasn't it?", "\"Yes, about fifteen trucks, because it was the first day of the season. People were tense.\""), .cross("You did not see the start of the argument, did you?", "\"No. I was at the far end checking a trailer. I only heard raised voices and came running.\"")],
        theory: ("{D} punched an angler.", "A cut line."),
        allocution: "\"Everyone had been waiting in the dark for a long time at that ramp, and I felt {V} cut in line. I lost my temper and punched. I'm sorry for {V}'s split lip. I'll apologize to {V} directly, and I'll stay patient on the water.\"",
        truths: ("{V} waited in line.", "{V} raised a hand."),
        defendant: [.direct("Did you punch {V}?", "\"Yes, I did. I thought {V} cut in line, and I lost my temper.\""), .direct("Why did you hit {V.him}?", "\"Everyone had been waiting a long time in the dark. I felt {V} cut, and I reacted.\""), .direct("Did you apologize?", "\"No. I did not. I was angry, and I walked off.\""), .direct("How long had you been waiting?", "\"Since about 4:30, and I was the third truck back. It was cold and I had a lot riding on the morning's fishing.\""), .direct("What did you see {V} do?", "\"{V} pulled in beside the line and edged forward in front of me. I told {V.him} to get back, and {V.he} said {V.he} had been there all along.\""), .direct("What did you do after you hit {V.him}?", "\"I stepped back and put my hands up. Then I got in my truck and waited my turn, and I did not speak to {V.him}.\""), .cross("{V} waited in line like everyone else, didn't {V.he}?", "\"Maybe so. I may have been wrong. I should have asked first.\""), .cross("You punched someone over a spot in a line, didn't you?", "\"I did. I know it is not worth it.\""), .cross("{V} was left with a cut lip. Do you feel any remorse?", "\"Yes. I should not have swung. I truly am sorry.\""), .cross("The attendant says {V} was in line, doesn't {V.he}?", "\"That is what the attendant says. I may have been wrong, and I will not argue with the person who runs the ramp.\""), .cross("You hit {V.him} once, in the mouth, didn't you?", "\"Yes, once, with a closed fist. I regret it every time I think of it.\"")],
        openings: ("At a boat ramp, the launch line formed at 5 a.m., and twenty minutes later {D} punched {V} in the mouth after an argument over the order. The ramp camera shows the blow, and {V} was left with a split lip.", "The defense will present evidence that {D} believed someone cut in line and lost a temper after waiting in the cold, and that {V} raised a hand first. {DL} swung once and stopped."),
        closings: ("A line, a punch, a cut lip, and a camera that shows it all. No place in line justifies striking someone in the face.", "One swing over a spot in a line, by an angler who regrets it. A minor cut and a single blow, after {V} raised a hand, is a lapse in judgment and not an attack on anyone."),
        timeline: [(0, "5 a.m.: the line."), (0, "5:20 a.m.: the punch.")],
        identified: "Ramp Camera",
        mood: .indifferent)

    static let raceTicketCopies = SmallCases.make(
        key: "story.raceTicketCopies",
        category: .whiteCollar,
        headlines: ["Man Sells Copied Race Tickets at the Gate"],
        law: "uttering",
        spec: "Uttered forged race tickets to {V}, a speedway, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} sold color copies of race tickets outside the gate on {DATE}. Sales began at noon, and the first scan came at 1 p.m. Nine copies carried the same serial.",
        state: [E(.physical, 3, "Copied Tickets", "Tickets with the same serial."), E(.statement, 2, "Gate Manager", "The scanner rejected nine tickets with the same serial.")],
        defense: [E(.statement, 1, "Resale", "{DL} says {D.he} resold real ones.")],
        role: "Gate manager",
        exam: [.direct("What did you see at the gate?", "\"Our scanner rejected nine tickets that carried the same serial number. That is not possible with real tickets.\""), .direct("What were those tickets?", "\"Color copies. They were color prints of a genuine ticket, sold outside the gate.\""), .direct("When did the sales begin?", "\"About noon, outside the gate. The first scan of a copy came at 1 p.m.\""), .direct("How do your tickets work at the gate?", "\"Each ticket has a unique serial and barcode that the handheld scanner reads once. A second scan of the same serial is rejected as already used.\""), .direct("How did you find out about the copies?", "\"Around one o'clock the scanner started rejecting tickets that had the same serial as one already admitted. We pulled nine and looked at them closely.\""), .direct("What did the tickets look like?", "\"They were color photocopies on slightly thinner paper, with a faint blur in the hologram strip. Side by side with a real one, the difference was visible.\""), .cross("Could the buyers tell the tickets were copies?", "\"Probably not. They look like real tickets at a glance. That is why people were fooled.\""), .cross("Did {D} say the tickets were real?", "\"{D} told deputies {D.he} thought they were real. I do not know what {D.he} knew.\""), .cross("Was the defendant selling at a fair price?", "\"I cannot say about the price. I only saw the rejected tickets.\""), .cross("The copies looked close enough to pass at a glance, didn't they?", "\"At a glance, yes. A buyer on the street would not likely notice the hologram.\""), .cross("You did not see the defendant making the copies, did you?", "\"No. I only saw tickets and heard from the buyers that they had paid {DL} outside the gate.\"")],
        theory: ("{D} sold copies.", "Real resale."),
        allocution: "\"I got those tickets from someone, and I assumed they were real, so I was only reselling extras a friend gave me. I use the copier at my job for documents, not for this. I'm sorry to the fans who couldn't get in. I'll refund every buyer.\"",
        truths: ("The copies were color prints.", "{DL} had a printer receipt."),
        defendant: [.direct("Did you know the tickets were copies?", "\"No. I thought they were real. I got them from someone, and I assumed they were fine.\""), .direct("Why did you have a printer?", "\"For work. I use it at my job for documents, and I did not use it for tickets.\""), .direct("What was your business that day?", "\"I was reselling extra tickets that a friend had given me, and I had a few of my own to sell. I stood by the gate and sold them at face value.\""), .direct("Where did you print the tickets?", "\"I printed copies at work, because a few friends wanted tickets for the same event and I only had one set. I did not think a color copy would cause a problem.\""), .direct("How did you find out they were fake?", "\"A buyer came back to the gate looking angry after the scanner refused the ticket. That is when I realized the problem.\""), .direct("What did you tell the buyers when they asked if the tickets were real?", "\"I said they were good for entry. I never checked a scanner myself, so I could not know whether they would work at the gate.\""), .cross("You printed color copies of race tickets, didn't you?", "\"Yes, I printed copies. I thought it was like a gift for friends.\""), .cross("You sold copies outside the gate for money, didn't you?", "\"I sold some. I did not realize it was fraud.\""), .cross("Nine copies had the same serial number. Doesn't that tell you?", "\"I did not look at the serials. In hindsight, yes.\""), .cross("You have a printer receipt for the color prints, don't you?", "\"Yes, I have a receipt from work for the color prints. I kept it because I did not think I was doing anything I had to hide.\""), .cross("Nine tickets carried the same serial, correct?", "\"So the gate manager says. I never looked at the serial numbers and never thought they mattered.\"")],
        openings: ("Outside a race gate, {D} sold color copies of tickets starting at noon, and by 1 p.m. the scanner had rejected nine tickets with the same serial. Buyers had paid for admission that never came.", "The defense witnesses will explain that {D} believed the tickets were real and never meant to cheat a buyer. {D.He} sold at face value and stayed at the gate when the problem arose."),
        closings: ("Nine tickets, one serial number, and color copies sold outside the gate at noon. Real tickets scan once, and these were printed to look like something they were not.", "{D} got the tickets from someone else and believed they were real. The State must prove {DL} knew they were copies when selling them, and the open sale at the gate points the other way."),
        timeline: [(0, "Noon: sales."), (0, "1 p.m.: the scan.")],
        identified: "Copied Tickets",
        mood: .indifferent,
        genders: ["D": .male])

    static let souvenirStroller = SmallCases.make(
        key: "story.souvenirStroller",
        category: .property,
        headlines: ["Woman Hides Souvenirs in Stroller Basket"],
        law: "larcenyMerchant",
        spec: "Took merchandise valued at $150 from {V}, a gift shop, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} hid souvenirs under a blanket in a stroller on {DATE}. {D.He} came in at 3 p.m. and left at 3:15 p.m. with a stroller. The five souvenirs were worth $150.",
        state: [E(.video, 3, "Shop Camera", "{D} slides items under a blanket."), E(.document, 2, "Price Tags", "Five souvenirs priced at $150 together.")],
        defense: [E(.statement, 1, "Forgot", "{DL} says {D.he} forgot them.")],
        role: "Shop clerk",
        exam: [.direct("What did your shop camera show at about 3 p.m.?", "\"It shows {D} walking in with a stroller and sliding souvenirs under a blanket in it, one item after another.\""), .direct("How many souvenirs were involved?", "\"Five. They were priced at $150 together. Each of them had a tag when it went on the shelf.\""), .direct("How long was {D} in the shop?", "\"About fifteen minutes, from 3 to 3:15. {D.He} left with the stroller and did not go to the register.\""), .direct("What sort of items were taken?", "\"Five souvenirs from the display by the door, including two mugs, a keychain, a small flag, and a postcard set. Each had a price tag from our shop.\""), .direct("What did you do after you saw the footage?", "\"I called the sheriff's office and gave the deputies the clip. Then I checked the shelf by the door and counted five items missing.\""), .direct("What did you notice at the door?", "\"{D.He} walked out without stopping at the register. The alarm did not sound because the items had no sensor tags.\""), .cross("Was a child in the stroller?", "\"Yes, a child was asleep in it. I did not see the child disturbed.\""), .cross("Were the tags still on the souvenirs when you recovered them?", "\"The tags were removed from the items. I found them detached when we got them back.\""), .cross("Did the defendant buy anything?", "\"No. {D.He} did not buy anything that I saw.\""), .cross("Did you see the child move at any point?", "\"No. The child stayed asleep through all of it, and the stroller hardly moved.\""), .cross("The tags were removed from the items, weren't they?", "\"Later, when a customer found some items on the street. I cannot say who took them off.\"")],
        theory: ("{D} hid items.", "Forgetfulness."),
        allocution: "\"I put the souvenirs in the stroller while I was looking around, and I forgot about them. I walked out with my child, not thinking. I'm sorry for the mistake. I'll pay for the five items and never leave a store distracted again.\"",
        truths: ("The tags were removed.", "The child was asleep."),
        defendant: [.direct("Did you put souvenirs under the blanket?", "\"Yes, I did. I put them there while I was looking, and I forgot about them. I was tired and distracted.\""), .direct("What about the tags?", "\"They fell off, I think. I did not take them off. I did not notice any tags at all.\""), .direct("Did you buy anything at the shop?", "\"No. I did not. I was just walking in and out with my child, and I never went to the register.\""), .direct("What was your day like?", "\"I had been up since five with a sick baby and no sleep. We went to the shop because I wanted to look for a gift for a friend.\""), .direct("Why did you put the items under the blanket?", "\"I picked them up and set them down on the stroller to free my hands, and then covered them to keep the sun off the baby. I did not think of them again.\""), .direct("When did you notice?", "\"At home, when I lifted the blanket to put the baby in the crib. I saw the mugs and felt sick, and I intended to bring them back.\""), .cross("You slid five items under a blanket in a stroller, didn't you?", "\"I did. That looks bad, I know. I was not thinking clearly.\""), .cross("How does a person forget five souvenirs under a blanket?", "\"I was exhausted, my child was asleep, and I was trying to keep the stroller moving.\""), .cross("You walked right past the register with a sleeping child and five hidden items, didn't you?", "\"I did, and I should have noticed. I truly am sorry.\""), .cross("You were in the shop for fifteen minutes and never picked up a basket, were you?", "\"No, I did not take a basket. I only had the stroller, and it took both hands to steer it around the displays.\""), .cross("The tags were pulled off before the items were found, weren't they?", "\"I do not recall taking them off. They may have come off when I moved things in the stroller.\"")],
        openings: ("A shop camera shows {D} sliding five souvenirs worth $150 under a blanket in a stroller at 3 p.m., then leaving fifteen minutes later without paying. The tags were later found removed.", "Jurors will also see a tired parent with a sleeping child who forgot the items under the blanket. {D} came back to the shop with a clear explanation."),
        closings: ("Five souvenirs went under a blanket in a stroller and out the door, with the tags removed. A sleeping child does not hide five items, but a blanket does.", "A distracted parent, a sleeping child, and a blanket. The State must prove {D} meant to take the items, and an exhausted caregiver forgot where they were."),
        timeline: [(0, "3 p.m.: the shop."), (0, "3:15 p.m.: the exit.")],
        identified: "Shop Camera",
        mood: .indifferent,
        genders: ["D": .female])

    static let chargerCable = SmallCases.make(
        key: "story.chargerCable",
        category: .property,
        headlines: ["Man Cuts and Takes Electric Charger Cable"],
