        closings: ("A slap on camera two minutes after the bite. {D} had time to cool down, saw the owner already holding the leash, and still chose to strike someone.", "The dog was off its leash and bit {D}. A slap in the heat of that moment, causing no injury, is a lapse that the law can weigh gently."),
        timeline: [(0, "6 p.m.: the bite."), (0, "6:02 p.m.: the slap.")],
        identified: "Street Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let barredSinger = SmallCases.make(
        key: "story.barredSinger",
        category: .publicOrder,
        headlines: ["Man Returns to Bar He Was Banned From and Sings"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a bar, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} returned to a bar on {DATE} after a written ban. {D.He} arrived at 9 p.m., and deputies came at 10 p.m. {D.He} had signed the notice a week earlier.",
        state: [E(.document, 3, "Ban Notice", "Signed notice."), E(.statement, 2, "Bartender", "Recognized {D} and called deputies.")],
        defense: [E(.statement, 1, "Unknown", "{DL} says {D.he} forgot.")],
        role: "Bartender",
        exam: [.direct("Who is {DL} to your bar?", "\"A patron who was banned in writing a week before. {D} signed the notice, and I kept the signed copy.\""), .direct("What happened on {DATE}?", "\"{D.He} arrived at 9 p.m. I recognized {D.him} and called deputies. Deputies came at 10 p.m.\""), .direct("Why did you wait an hour?", "\"I called as soon as I recognized {DL}. Deputies take time to arrive, and I couldn't make {DL} leave myself.\""), .direct("What is the ban notice?", "\"A one-page notice that I handed to {DL} after a loud argument with another customer. It says {DL} may not enter the bar for twelve months and carries {DL}'s signature and the date.\""), .direct("What happened when {D} walked in?", "\"I recognized {DL} right away and told {DL} that the ban was in force. {DL} said something about forgetting and ordered a soda.\""), .direct("What did you do about it?", "\"I called the sheriff's office at nine-oh-five and told them a banned patron was inside. Deputies arrived at ten.\""), .cross("{DL} says {D.he} forgot about the ban, doesn't {D.he}?", "\"It was just a week. I'd have thought it was memorable.\""), .cross("Did {DL} cause trouble?", "\"Not that I recall. {D.He} sat and was fine. The issue was the ban, not behavior.\""), .cross("Did you tell {DL} to leave?", "\"I told {DL} it wasn't allowed. {DL} stayed until deputies came.\""), .cross("{D} was quiet during that hour, wasn't {D.he}?", "\"Yes. {D.He} sat at the end of the bar, sipped a soda, and sang along once with the jukebox.\""), .cross("Karaoke was going that night, wasn't it?", "\"We had a small open mic. {D.He} sang one song and got applause, which is why I did not push it harder.\"")],
        theory: ("{D} ignored a ban.", "Forgot."),
        allocution: "\"I signed the notice, but a week passed and I'd fallen out of the habit of thinking about it. It's my regular bar, and I walked in on autopilot. I stayed too long when I was told to leave. I'm sorry for the trouble, and I'll find another place.\"",
        truths: ("{DL} signed it a week earlier.", "{DL} sang for an hour."),
        defendant: [.direct("Did you know you were banned?", "\"Yes, I'd signed the notice. But a week passed and I was out of the habit. I forgot when I walked in.\""), .direct("Why did you come back?", "\"It's my regular bar. I walked in out of habit. I didn't think about the notice.\""), .direct("What happened when the bartender recognized you?", "\"I was told to leave, and I stayed too long. I should have left right away.\""), .direct("How long had you come to that bar?", "\"About six years. I have a regular stool and I know the staff by name.\""), .direct("What did you think when you walked in?", "\"I was on autopilot after work and did not stop to remember the notice. I realized when the bartender looked at me.\""), .direct("Why did you stay?", "\"I did not want a fuss in front of the room. I figured I would finish the soda, then go.\""), .cross("You signed the notice a week earlier, didn't you?", "\"Yes. I know I did. I signed it and I still came back.\""), .cross("You stayed for an hour, didn't you?", "\"Yes. I should have left. I felt embarrassed and didn't want a scene.\""), .cross("The bartender told you it wasn't allowed, didn't the deputy?", "\"Yes. I heard. I stayed anyway. I'm sorry.\""), .cross("You came in at 9 p.m. and sat on your usual stool, didn't you?", "\"Yes, I ordered a soda and sat on my usual stool. I did not think anyone would mind one drink.\""), .cross("You were told twice that you were not allowed, correct?", "\"Yes, once by the bartender and once by the deputy. I should have left the first time.\"")],
        openings: ("A week after signing a written ban, {D} walked back into the bar at 9 p.m. The bartender called deputies, and {DL} stayed for an hour, until they arrived at 10 p.m.", "Jurors will also see a regular of six years who forgot a week-old ban out of habit and who caused no trouble. {D} sang one song and ordered a soda."),
        closings: ("A signed ban, a return a week later, and an hour in the bar until deputies came. {D} knew the notice and stayed after being told.", "{D} forgot and walked in out of habit, sat quietly, and caused no trouble at all. The State must prove a knowing return, and a regular on autopilot is not that."),
        timeline: [(0, "9 p.m.: arrival."), (0, "10 p.m.: deputies.")],
        identified: "Ban Notice",
        mood: .indifferent,
        genders: ["D": .male])

    static let lifeguardChair = SmallCases.make(
        key: "story.lifeguardChair",
