        state: [E(.video, 3, "Pool Camera", "{D} throws a chair."), E(.statement, 2, "Lifeguard", "Blew the whistle at a running child.")],
        defense: [E(.statement, 1, "Anger", "{DL} says the guard blew the whistle at {D.his} child.")],
        role: "Pool manager",
        exam: [.direct("What happened at your pool at 2 p.m.?", "\"A lifeguard blew the whistle at a running child. Five minutes later, {D} screamed at the lifeguard and threw a chair.\""), .direct("What does the pool camera show?", "\"It shows {DL} throwing a chair. It lands near the deck. No one was hit, but it was close to other swimmers.\""), .direct("Why was the whistle blown?", "\"A child was running on the pool deck. The rule is no running, and the guard enforces it.\""), .direct("How does your pool keep order on the deck?", "\"We post rules at the entrance, including no running. Lifeguards are in chairs around the pool with whistles, and they remind guests when needed.\""), .direct("What did you do after the chair was thrown?", "\"I walked over, asked {D.him} to step outside, and called the sheriff's office. The guard was shaken, so I had another guard take over the chair.\""), .direct("What did {D} do about five minutes later?", "\"{DL} walked up to the guard's chair, shouted that the guard had no right to embarrass a child, and then picked up a plastic chair and threw it. It landed on the deck about ten feet from the guard.\""), .cross("Whose child was it?", "\"It was {D.his} child, I understand. I did not see that until after.\""), .cross("Was the defendant warned before?", "\"Yes. {D.He} was warned about the rules earlier. I do not know exactly how.\""), .cross("Was anyone hurt?", "\"No. The chair hit the deck and did not strike anyone.\""), .cross("The guard was a teenager, wasn't the guard?", "\"The guard was nineteen and had completed training. I stood nearby while it happened.\""), .cross("The chair landed away from the swimmers, didn't it?", "\"It landed on the deck near the lifeguard stand, away from the water. No one was within several feet.\"")],
        theory: ("{D} threw a chair.", "Anger."),
        allocution: "\"My child was running a little, and I thought the whistle was too harsh in front of everyone. I felt humiliated, and I threw that chair without thinking. I'm sorry to the lifeguard who was only doing a job. I'll apologize to the pool.\"",
        truths: ("The whistle was for running.", "{DL} was warned."),
        defendant: [.direct("Did you throw the chair?", "\"Yes, I did. I was angry at the whistle, and I threw it without thinking.\""), .direct("Why were you so angry?", "\"The lifeguard blew a whistle at my child in front of everyone. I felt embarrassed and defensive.\""), .direct("Whose child was running?", "\"Mine. My child was running a little, and I thought the whistle was too harsh.\""), .direct("What did you see that afternoon?", "\"The whistle blew loudly in the middle of a crowded deck, and everyone turned toward my child. I felt like I was being called out in front of the neighbors.\""), .direct("Why did you pick up the chair?", "\"I do not know. I was angry and wanted to make a point, and the chair was beside me.\""), .direct("What did you do afterward?", "\"I put my child in the car and left. I called the pool the next morning to apologize.\""), .cross("The rule is no running, isn't it?", "\"Yes. I know it is. I should have said thank you and corrected my child.\""), .cross("You screamed at a teenager doing a job, didn't you?", "\"I did. I am ashamed of it.\""), .cross("A chair thrown near swimmers could hurt someone, couldn't it?", "\"Yes. I did not think. I am glad no one was hurt.\""), .cross("The warning earlier was about the same rule, wasn't it?", "\"Yes, a different guard had told us earlier about running. I did not take it well.\""), .cross("The guard was not rude to you, was the guard?", "\"No. The whistle was routine, and my reaction had nothing to do with the guard.\"")],
