        defense: [E(.statement, 1, "Dare", "{DL} says it was a dare.")],
        role: "City public works supervisor",
        exam: [.direct("What happened to the bus bench on {DATE}?", "\"A bench on a city bus route was smashed. The bat came out at 11 p.m., and the bench broke about five minutes later.\""), .direct("What does the street camera show?", "\"It shows {D} swinging a bat at the bench. You can see the swings and the bench breaking.\""), .direct("What did it cost to replace?", "\"$700. The repair invoice is in evidence. Riders lost the bench for a week.\""), .direct("Where is the bench and who uses it?", "\"It is a concrete and wood bench at a stop on a busy city route, used by commuters and students every day. We replaced it two years ago.\""), .direct("What did the camera show in the late evening?", "\"{DL} and two others stop at the bench around eleven. {DL} takes a bat out of a bag and starts swinging, and the slats splinter.\""), .direct("What was the damage?", "\"The bench was broken into pieces and the concrete base cracked. Replacing it and hauling away debris cost $700.\""), .cross("{DL} says it was a dare, doesn't {D.he}?", "\"I can't say who dared whom. The camera shows {DL} swinging.\""), .cross("Was anyone hurt?", "\"No. It was late and no one was at the stop. It could have been dangerous.\""), .cross("Did {DL} try to flee?", "\"I don't recall. The camera shows {DL} swinging. I wasn't there at the time.\""), .cross("Another person filmed the swinging, didn't they?", "\"A friend appears to hold a phone in the footage. I do not know where that video went.\""), .cross("No pedestrians were nearby, were they?", "\"The street was empty at that hour. Nobody was struck, and no vehicles stopped.\"")],
        theory: ("{D} smashed a bench.", "A dare."),
