        defense: [E(.statement, 1, "Souvenir", "{DL} says they were gifts.")],
        role: "Resort manager",
        exam: [.direct("What did housekeeping find after {D} checked out?", "\"Eight items were missing from the room, including robes and towels. {D} had checked out in the morning.\""), .direct("Are guests allowed to take the robes?", "\"No. Signs in the rooms say the robes are not to be taken. They are for use during the stay.\""), .direct("What does the resort provide in rooms?", "\"Robes, towels, and a few toiletries. A small card on the closet door says the robes and towels belong to the resort and are available in the gift shop.\""), .direct("What did housekeeping report?", "\"Two robes, four bath towels, and two hand towels missing after checkout. They counted against the room inventory we keep for each room.\""), .direct("What does the hall camera show?", "\"{D.He} comes out of the room around nine with a large duffel and sets it in the hall while closing the door. The bag is visibly full and heavy.\""), .direct("How did you decide the missing items were not left behind by mistake?", "\"The robes and towels were stripped from the hooks and shelves, and the room still looked tidy. That pattern told me they had been packed on purpose.\""), .cross("Did the defendant take all eight items?", "\"The inventory shows eight items missing. I assume {DL} took them, but I did not see it.\""), .cross("Do resorts sell their robes?", "\"Some do, at the gift shop. Ours does too, but {D.he} did not buy any.\""), .cross("Did the defendant deny taking them?", "\"No. {DL} said they thought the items were gifts.\""), .cross("Guests sometimes ask about buying robes, don't they?", "\"Yes, and we sell them for $85 each at the gift shop. Many guests do buy one.\""), .cross("{D} was cooperative when you asked about it, wasn't {D.he}?", "\"Yes. {D.He} was polite and said the robes seemed like gifts.\"")],
