        truths: ("Signs say not to take them.", "{DL} took eight items."),
        defendant: [.direct("Did you take the robes and towels?", "\"Yes, I did. I thought they were gifts for guests, like the little soaps and the bottles of shampoo.\""), .direct("Why did you think they were gifts?", "\"The resort felt generous, and the robes were very nice. I assumed they were part of the stay.\""), .direct("Did you ask the front desk about it?", "\"No, I did not ask anyone at the front desk. I should have, and I see that now.\""), .direct("What was your stay like?", "\"A weekend anniversary trip. The staff were friendly, and welcome cards and chocolates were left in the room.\""), .direct("Why did you take the towels too?", "\"The room felt luxurious, and I assumed the whole package was a resort gift. I did not stop to ask anyone.\""), .direct("What did you do when you were contacted?", "\"I answered every question and offered to send back what I could. I did not argue at all.\""), .cross("There are signs in the room saying not to take the robes, aren't there?", "\"Yes. I did not see them, or I ignored them. I am honestly not sure which.\""), .cross("You took eight items. Doesn't that seem like a lot for a souvenir?", "\"In hindsight, yes, it does. I was not thinking clearly, and I packed too much.\""), .cross("Will you pay for what you took?", "\"Yes. I would be glad to pay for everything I took from the resort.\""), .cross("You never saw the card on the closet door, did you?", "\"I do not recall it. If it was there, I walked right past it.\""), .cross("You packed the items in your suitcase the night before checkout, didn't you?", "\"Yes, I packed them the night before with everything else. I did not think of them as anything different from my own clothes.\"")],
        openings: ("A resort guest, {D}, checked out in the morning, and housekeeping found eight items missing from the room, including two robes and several towels. The hall camera shows {DL} with a full bag, and signs in the room say the robes are not to be taken.", "By the end of this trial, the proof will show that {D} thought the robes were courtesy gifts, never hid the bag, and has offered to pay. {D.He} did not ask because the stay felt generous."),
        closings: ("Eight items gone from the room, signs saying not to take them, and a full bag on camera. A robe sold in the gift shop is not a free souvenir.", "A guest who thought the robes were a courtesy gift and never asked the front desk. A mistake about a resort's customs is not a plan to steal."),
        timeline: [(0, "Checkout."), (0, "Housekeeping counts.")],
        identified: "Hall Camera",
        mood: .indifferent)

    static let gymClose = SmallCases.make(
        key: "story.gymClose",
        category: .whiteCollar,
        headlines: ["Gym Owner Sells Year Memberships Then Closes"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $700, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} sold year memberships on {DATE} and closed the gym a month later. The eviction notice came fourteen days before the sale. {D.He} kept selling memberships after the notice arrived.",
        state: [E(.document, 3, "Receipts", "Sold on the closing date."), E(.document, 2, "Eviction Notice", "A notice dated fourteen days before the sale.")],
        defense: [E(.statement, 1, "Lease", "{DL} says the landlord evicted {D.him}.")],
        role: "Member",
        exam: [.direct("What did you buy from {DL}?", "\"A year membership at the gym. I paid up front. The gym closed a month later and I lost the money.\""), .direct("What do you know about the sales?", "\"Receipts show memberships sold on the closing date. An eviction notice was dated fourteen days before the sale.\""), .direct("What did {DL} do after the notice?", "\"{D} kept selling memberships after the notice arrived. That's what the receipts show. I would not have joined had I known.\""), .direct("How did you find the gym?", "\"A neighbor recommended it. The owner offered a year membership for a discounted price if I paid up front, and I paid by card.\""), .direct("What did you learn after the closing?", "\"The door was locked one morning and a landlord's notice was on the glass. It was dated two weeks before I signed up.\""), .direct("How many members were affected?", "\"A group message went around, and at least thirty of us had paid for the year. We figure around $20,000 in all.\""), .cross("{DL} says the landlord evicted {D.him}, doesn't {D.he}?", "\"I don't doubt the landlord evicted {DL}. I just wish {DL} had told members.\""), .cross("Did you see the eviction notice?", "\"I saw it afterward. I didn't see it when I joined. No one told us.\""), .cross("Did {DL} give refunds?", "\"I haven't gotten one. I don't know about the others. I paid for a year and got a month.\""), .cross("{D} did say the landlord was behind this, didn't {D.he}?", "\"That is what {DL} said afterward. {DL} claimed the landlord shut the gym, but the notice was already two weeks old when I paid.\""), .cross("You do not know what the defendant planned to do with the money, do you?", "\"No. I only know that nothing came back to us.\"")],
        theory: ("{D} took memberships.", "An eviction."),
        allocution: "\"The landlord evicted me, and I couldn't keep the gym open. I thought I could work something out and meant to keep it going. I never wanted anyone to lose money. I'm sorry to every member who paid a year up front, and I'll repay them.\"",
        truths: ("{DL} kept selling after the notice.", "The notice is real."),
        defendant: [.direct("Why did you close the gym?", "\"The landlord evicted me. I didn't have a choice. I couldn't keep the gym open without a lease.\""), .direct("Why did you keep selling memberships?", "\"I thought I could work it out with the landlord. I thought I'd stay in the space. I didn't think it would close.\""), .direct("Did you mean to cheat members?", "\"No. I never wanted anyone to lose money. I meant to keep the gym open.\""), .direct("How did the eviction come about?", "\"The landlord raised the rent beyond what I could pay and gave me a notice. I was told the gym would close in about a month.\""), .direct("What did you plan to do?", "\"I hoped to negotiate or move the gym to a new space. I kept selling because I needed the cash to cover a new location.\""), .direct("What happened to the money?", "\"It went to rent, equipment loans, and the deposit on a new site that fell through. I do not have it now.\""), .cross("The notice came fourteen days before the sale, didn't it?", "\"Yes. I knew about it. I thought I could fix it.\""), .cross("You kept selling after the notice arrived, didn't you?", "\"Yes. I should have stopped. I let hope get ahead of the truth.\""), .cross("You didn't tell members about the eviction, did you?", "\"No. I didn't want them to leave. I regret it now.\""), .cross("You never told members about the notice, did you?", "\"No. I was afraid they would cancel and I would lose any chance of staying.\""), .cross("Members paid for a full year up front, didn't they?", "\"Yes, most paid for a whole year at once, and the gym closed a month later. I understand what that cost them.\"")],
        openings: ("{D} sold year memberships at a gym that closed a month later. An eviction notice had arrived fourteen days before the sale, and members who paid up front never got what they bought.", "The defense will point to a gym owner evicted by a landlord, who hoped to keep the doors open and did not plan to close. {D} lost the money to the same failure that cost members theirs."),
        closings: ("An eviction notice, fourteen days of silence, and year memberships sold anyway. Members paid for a year and got a locked door.", "{D} hoped to work things out and never planned to close. The State has not proved {DL} meant to take the money knowing the gym would not survive."),
        timeline: [(-14, "The eviction notice."), (0, "The sale.")],
        identified: "Receipts",
        mood: .indifferent)

    static let greenhouseRocks = SmallCases.make(
        key: "story.greenhouseRocks",
        category: .property,
        headlines: ["Neighbor Throws Rocks Through Greenhouse Panels"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, causing damage of $1,100, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} threw rocks through a neighbor's greenhouse panels on {DATE}. The dog barked from midnight, and the rocks came thirty minutes later. Twelve panels were broken.",
        state: [E(.video, 3, "Yard Camera", "{D} throws rocks."), E(.document, 2, "Replacement Estimate", "$1,100 to replace twelve panels.")],
        defense: [E(.statement, 1, "Dog", "{DL} says a dog barked all night.")],
        role: "Neighbor",
        exam: [.direct("What happened to your greenhouse on {DATE}?", "\"Rocks came through the panels about thirty minutes after my neighbor's dog started barking at midnight. Twelve panels were broken.\""), .direct("What does your yard camera show?", "\"It shows {D} throwing rocks. It shows the rocks flying toward the greenhouse and the panels breaking.\""), .direct("What did it cost?", "\"$1,100 to replace twelve panels. I have the estimate. Some of my plants were exposed too.\""), .direct("What is the greenhouse like?", "\"A twelve by sixteen foot structure with polycarbonate panels, where I grow tomatoes and herbs. I built it two years ago and it was nearly full of seedlings.\""), .direct("What did you hear that night?", "\"Glass-like cracks from the back of the yard at around half past midnight. I came to the window and saw someone throwing fist-sized rocks.\""), .direct("What damage did you find?", "\"Twelve panels were cracked or shattered, and several seedlings were crushed. The estimate to replace the panels is $1,100.\""), .cross("{DL} says a dog barked all night, doesn't {D.he}?", "\"The dog barked from midnight. That doesn't explain throwing rocks at my greenhouse.\""), .cross("Is the dog yours?", "\"It belongs to my household. I know it barks sometimes. I've worked on it.\""), .cross("Did {DL} come to you about the dog?", "\"Not that night. I don't recall {D.he} ever coming to my door about it.\""), .cross("Your dog barks a lot, doesn't it?", "\"The dog does bark at night when something moves outside. I have heard it can go on.\""), .cross("{D} complained to you once before, didn't {D.he}?", "\"Once, a few weeks earlier. I told {DL} I would try to bring the dog inside, and I did not follow through every night.\"")],
        theory: ("{D} broke panels.", "A dog."),
        allocution: "\"I threw those rocks toward the yard, not at the glass. The dog had barked steady and sharp from midnight on, and I had work at six. I lost my temper. I'm ashamed, and I'm willing to pay for the twelve panels.\"",
        truths: ("{DL} complained once.", "Twelve panels were broken."),
        defendant: [.direct("Did you mean to break the greenhouse?", "\"No. I threw them toward the yard, not at the panels. I didn't aim for the glass.\""), .direct("How are you coping with what happened?", "\"Ashamed. I'm willing to pay. I lost my temper because of the noise.\""), .direct("What did the barking sound like?", "\"Steady and sharp, every few seconds from midnight on. I had work at six and had not slept at all.\""), .direct("What did you do first?", "\"I called out over the fence and banged on the gate. Nobody answered, and the barking kept going.\""), .direct("Why did you throw rocks?", "\"I picked up some from my garden edging and threw them toward the noise. I meant to scare the dog, and I did not see the greenhouse.\""), .direct("How many nights had the dog been barking before you threw the rocks?", "\"About a week of nights. I had slept very little, and by that night I was not thinking clearly about what I was doing.\""), .cross("The camera shows you throwing rocks, doesn't it?", "\"Yes. That's me. I can't deny it.\""), .cross("Twelve panels were broken, weren't they?", "\"Yes. That's a lot. I didn't mean it to be so many.\""), .cross("You waited thirty minutes after the barking began, didn't you?", "\"Yes. I held out as long as I could. Then I snapped.\""), .cross("You threw more than one rock, didn't you?", "\"Yes, a handful. I kept throwing until I heard the panels crack.\""), .cross("You could have called the sheriff's office about the dog, couldn't you?", "\"Yes. I thought about it, but it was late and I let temper take over.\"")],
        openings: ("After a dog barked from midnight, {D} threw rocks through twelve panels of a neighbor's greenhouse thirty minutes later. The yard camera shows the throwing, and replacing the panels costs $1,100.", "The defense will present a sleepless neighbor driven to a bad moment by a dog barking all night. {D} meant to startle the dog and has offered to pay."),
        closings: ("Rocks thrown on camera, twelve panels broken, and $1,100 to replace them. A barking dog gives no one the right to throw rocks at a neighbor's yard.", "A dog barked all night, and {D} snapped. {D.He} owns up and will pay, and the State has not proved a plan to destroy a greenhouse."),
        timeline: [(0, "Midnight: the dog."), (0, "12:30 a.m.: the rocks.")],
        identified: "Yard Camera",
        mood: .indifferent)

    static let lunchBenefits = SmallCases.make(
        key: "story.lunchBenefits",
        category: .whiteCollar,
        headlines: ["Man Lies on Application to Get Free Lunch Benefits"],
        law: "falsePretenses",
        spec: "Obtained property of {V}, a school district, by deception, $300, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} understated income on an application for school lunch benefits on {DATE}. The application was filed sixty days before the review, and {D.he} signed it twice. The form lists no income.",
        state: [E(.document, 3, "Application", "A listed income of $0."), E(.document, 2, "Pay Stubs", "Pay stubs showing $3,000 a month.")],
        defense: [E(.statement, 1, "Mistake", "{DL} says {D.he} misread the form.")],
        role: "District clerk",
        exam: [.direct("What did the lunch benefits application say?", "\"It listed an income of $0. {D} signed it twice, and the application was filed sixty days before our review.\""), .direct("What did the review find?", "\"Pay stubs showing about $3,000 a month in income. That is far above what the form said.\""), .direct("Why does the form matter?", "\"Benefits are based on income. A listed income of $0 qualifies a family for free lunches.\""), .direct("What does the application ask?", "\"It asks for household size and monthly income from all adults. The form is two pages with a certification at the bottom that the information is true.\""), .direct("How was the application reviewed?", "\"Each year we verify a sample with pay stubs. This one was selected sixty days after it was filed.\""), .direct("What did the pay stubs show?", "\"Steady wages of about $3,000 a month from a full-time job for the previous year. The application had income marked as zero.\""), .cross("Did {D} read the form before signing?", "\"I cannot say. The form is long, and many parents sign quickly.\""), .cross("Could the defendant have misunderstood the income question?", "\"It is possible. The question is not always clear to a parent.\""), .cross("Did the defendant sign twice?", "\"Yes, in two places. I know that is standard.\""), .cross("The form has several boxes for income, doesn't it?", "\"Yes, separate lines for wages, benefits, and other income. A person could miss the wage line if they are skimming.\""), .cross("Benefits were not granted in the amount of the full price, were they?", "\"They were granted at the free level, which saved the family about $55 a month in lunches. The review reversed it.\"")],
        theory: ("{D} lied on a form.", "A misreading."),
        allocution: "\"I did not mean to lie. I was in a hurry and didn't read the form closely, and I trusted it was filled out correctly when I signed twice. I'll fix the application and repay any benefits I shouldn't have received.\"",
        truths: ("Pay stubs show $3,000.", "{DL} signed twice."),
        defendant: [.direct("Did you lie about your income on the form?", "\"No. I did not lie. I did not read the form closely and I made a mistake.\""), .direct("Did you sign it?", "\"Yes, I signed it twice. I trusted the form was filled out correctly.\""), .direct("Did you read the form before signing?", "\"Not closely. I was in a hurry, and I did not read every line.\""), .direct("How did you fill out the form?", "\"I sat at the kitchen table after work and checked the boxes quickly. My child had to bring it back the next morning.\""), .direct("What did you understand it to ask?", "\"I thought it asked only about benefits like welfare, not wages. I put zero on the line that looked like that.\""), .direct("What did you do when the review letter came?", "\"I called the district and explained that I had misread it. I brought in pay stubs and offered to pay for the lunches.\""), .cross("The form says $0 income. Your pay stubs show $3,000 a month. How is that a mistake?", "\"I do not know how it was written. I did not check.\""), .cross("Who filled in the income line?", "\"I filled in some of it. I may have left that blank.\""), .cross("You signed a statement under penalty without reading it, didn't you?", "\"I did. I know that was careless.\""), .cross("Your pay stubs are in your own name, aren't they?", "\"Yes, the stubs are in my name and I am paid every two weeks. I did not think about the stubs when I filled out the form.\""), .cross("Your family does earn about $3,000 a month, doesn't it?", "\"Yes. I have never denied that, and I would have written it down if I had understood.\"")],
        openings: ("A school lunch benefits application listed an income of $0, and {D} signed it twice. Pay stubs reviewed sixty days later show about $3,000 a month in wages.", "Listen for the defense evidence, which will show that {D} did not read the form closely and thought it asked only about benefits. {D.He} brought in pay stubs and offered to repay."),
        closings: ("An application showing $0 income and signed twice, when pay stubs show $3,000 a month. A signature under a true-statement line is not a decoration.", "{D} signed in a hurry and never read the form closely. The State must prove {DL} meant to deceive the district, and {D.he} was open with the pay stubs when asked."),
        timeline: [(-60, "The application."), (0, "The review.")],
        identified: "Application",
        mood: .indifferent,
        genders: ["D": .male])

    static let propaneShort = SmallCases.make(
        key: "story.propaneShort",
        category: .whiteCollar,
        headlines: ["Seller Fills Propane Tanks Short and Charges Full"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $180, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} charged for full propane tanks on {DATE} but filled each only halfway. The sale was in the morning, and the tanks were weighed that evening. The tanks had been sold as full.",
        state: [E(.physical, 3, "Tanks", "Half-full by weight."), E(.document, 2, "Weight Records", "Tank weights recorded at the weigh-in.")],
        defense: [E(.statement, 1, "Gauge", "{DL} says the gauge was off.")],
        role: "Customer",
        exam: [.direct("What did you buy from {D}?", "\"Propane tanks. The sale was in the morning, and the tanks were sold to me as full.\""), .direct("What did you find when you weighed them?", "\"That evening, the tanks were half full by weight. The weight records show it.\""), .direct("How was the scale?", "\"The scale was calibrated. I used a scale that I know is accurate.\""), .direct("Why did you buy propane from the defendant?", "\"I run a camp stove and a grill and buy several tanks a season. {D}'s stand was cheaper than the hardware store, so I bought four tanks at the full price.\""), .direct("How did you test the tanks?", "\"At home that evening I weighed them on a calibrated kitchen scale against the empty weight printed on each collar. All four came in near half the full weight.\""), .direct("What did the defendant say when you went back?", "\"{D.He} was surprised and said the gauge must have read full. I asked for a refund, and {D.he} said to come back another day.\""), .cross("Gauges can be off, can't they?", "\"Yes. They can. But the scale is not a gauge, and it showed half.\""), .cross("Have others complained about the defendant?", "\"I have heard that {D.he} had other complaints.\""), .cross("Did the defendant refund you?", "\"Not at first. I had to ask more than once.\""), .cross("The gauge on a tank can be wrong, can't it?", "\"Sometimes, but the scale does not guess. Four tanks in a row at half is a pattern.\""), .cross("You were refunded eventually, weren't you?", "\"After two visits, yes. I do not know why it took that long.\"")],
        theory: ("{D} shorted tanks.", "A bad gauge."),
        allocution: "\"I believed those tanks were full, because the gauge reads full when it isn't. I trusted it and should have checked it more often. I'm sorry to every customer who paid for a full tank. I'll refund them and replace the gauge.\"",
        truths: ("The scale was calibrated.", "{DL} had complaints."),
        defendant: [.direct("Did you short the tanks?", "\"No. I did not fill them halfway on purpose. I believed they were full.\""), .direct("What about the gauge?", "\"It was off. The gauge reads full when it is not. I trusted it.\""), .direct("Do you check your scale?", "\"Sometimes. I should check it more often. I did not realize it was off.\""), .direct("How do you fill tanks?", "\"I use a filling hose attached to a large supplier tank, and I watch the gauge on each cylinder. Full is when the needle reaches the top mark.\""), .direct("What was wrong with the gauge?", "\"The gauge was cheap and sticky, and it read full when the tank was only half. I found out when the customer came back.\""), .direct("What have you done since?", "\"I replaced the gauge and bought a floor scale to weigh every tank. I refunded the customer and offered a free refill.\""), .cross("The customer's scale shows half full, doesn't it?", "\"Yes. I know that now. I do not dispute the number.\""), .cross("You charged full price for half the propane, didn't you?", "\"I did, but I did not know. I would not do that on purpose.\""), .cross("You have had complaints before, haven't you?", "\"A few. I fixed them. I try to be fair.\""), .cross("You never weighed the tanks before selling, did you?", "\"No. I trusted the gauge, and I should have used a scale from the beginning.\""), .cross("You had other complaints before this, didn't you?", "\"A couple, and I fixed those. I did not look for what they had in common.\"")],
        openings: ("{D} sold four propane tanks as full, and the customer weighed them that evening and found them only half full. The scale was calibrated, and {D.he} charged the full price.", "The defense case is that {D}'s gauge was off, that {DL} believed the tanks were full, and that {DL} refunded the customer once the problem was clear. {D.He} has since bought a scale."),
        closings: ("Tanks sold as full, weighed at half, on a calibrated scale. A seller who charges for a full tank is responsible for knowing what is in it.", "A gauge that read full and a seller who trusted it. An honest mistake with equipment is not fraud, and {D} fixed the problem."),
        timeline: [(0, "Morning: the sale."), (0, "Evening: the weigh-in.")],
        identified: "Tanks",
        mood: .indifferent)

}
